    ('557fc5a4-6e81-522e-bff2-760cda45604c', 'reKgQh0E9kg', 122, 765150, 768180, 'And then I go to sleep.'),
    ('f28b8d57-c1ff-5db9-9b05-3d604e563ad9', 'ri2uKTpw4lQ', 1, 21230, 28822, 'In the United Kingdom, Sunday is normally the first day on the calendar,'),
    ('9ea54b3e-17ff-5841-8e1c-cacdfd2b4a0b', 'ri2uKTpw4lQ', 2, 28822, 35122, 'so I am going to tell you what I normally do on Sundays first.'),
    ('6f4016e5-6dc5-5cc2-83cc-8d394b67b2f6', 'ri2uKTpw4lQ', 3, 48656, 57889, 'I normally cook a lot of food because then I can eat it on Monday or Tuesday, for example,'),
    ('702ffab8-0c13-55dd-8ac6-353486248bf8', 'ri2uKTpw4lQ', 4, 57889, 62813, 'and that way I don''t have to cook every day.'),
    ('381a5951-8a1d-56be-9e3a-558c27d6c2b8', 'ri2uKTpw4lQ', 5, 78892, 89017, 'Mondays, Tuesdays, Wednesdays and Thursdays are very similar for me, but Mondays are definitely the worst day of the week.'),
    ('fde4ba7a-99c2-5e69-8361-71419f30c25f', 'ri2uKTpw4lQ', 6, 96272, 103673, 'When I wake up on these days, I brush my teeth, I get dressed, I brush my hair,'),
    ('792b48c7-80a7-512b-9d3f-c23f6b1c3050', 'ri2uKTpw4lQ', 7, 110670, 116985, 'I always have my lunch at work because then I don''t have to prepare it.'),
    ('b31418e9-10f5-5177-b9dd-58fc14f53033', 'ri2uKTpw4lQ', 8, 116985, 117950, 'In the UK,'),
    ('e141e8b0-0737-50c1-b0f8-a3d6220522b2', 'ri2uKTpw4lQ', 9, 117950, 130065, 'people normally have breakfast in the morning after they wake up and they normally have some cereals and milk and a cup of coffee or a cup of tea.'),
    ('31bbca7c-bb78-572f-8d14-84e3b853def6', 'ri2uKTpw4lQ', 10, 150031, 159177, 'I normally have dinner and before I go to bed I play with my cat because she has got a lot of energy.'),
    ('925dd2f3-c2d7-58ad-a026-9dca25ce0871', 'ri2uKTpw4lQ', 11, 159177, 169141, 'If I don''t play with my cat, she doesn''t sleep at night, so this is an important thing for me to do.'),
    ('8a1b8a45-56fb-58fc-842c-243d6c0b7b13', 'ri2uKTpw4lQ', 12, 178470, 192607, 'This is the biggest meal of the day and the typical British dinner is a roast dinner, which includes some meat, chicken or fish, some potatoes,'),
    ('9214d08f-62a0-57f4-83c6-98d268d36c8a', 'ri2uKTpw4lQ', 13, 192607, 198992, 'some vegetables like carrots, broccoli or peas.'),
    ('4bf75012-c957-5d19-930f-b0889414a77c', 'ri2uKTpw4lQ', 14, 198992, 211169, 'However, people obviously don''t eat this every day, and they might eat a pasta dinner, curry, a pie or something like that.'),
    ('b8b94941-818e-5eaa-a8db-9f97bf66f9a5', 'ri2uKTpw4lQ', 15, 211169, 217619, 'Before going to bed, some people have a snack that is called supper.'),
    ('3ec35df8-ea5e-5eed-91f5-ce9762294616', 'ri2uKTpw4lQ', 16, 218270, 225940, 'Depending on if you are hungry or not, people will have a bigger or a smaller supper.'),
    ('24600536-d791-5b18-a4bf-0697f5666da3', 'ri2uKTpw4lQ', 17, 226670, 231435, 'On Fridays, I am normally happier because it is the weekend.'),
    ('18a70f7b-ec52-58a0-9ebd-fbbe4c3ea2b1', 'ri2uKTpw4lQ', 18, 231435, 236548, 'In the evening I go for a walk or watch a series on Netflix.'),
    ('11ea9e56-4f88-5c1e-9ae7-230b11f13911', 'ri2uKTpw4lQ', 19, 236548, 244740, 'I like Fridays but I don''t have a lot of energy so I normally relax and stay at home.'),
    ('959cb3c1-1393-5008-b010-d6b44bf9d26d', 'ri2uKTpw4lQ', 20, 244740, 249150, 'Finally, I normally eat out on Saturdays.'),
    ('c4ce7f09-824c-5bae-8354-e65a9f123c68', 'ri2uKTpw4lQ', 21, 249150, 256020, 'My favorite type of restaurants are Italian restaurants because I love pasta and pizza.'),
    ('e6e3ae32-d72c-5fd6-b6cd-1260122da109', 'ri2uKTpw4lQ', 22, 256670, 258514, 'After having dinner,'),
    ('519f8e0c-eded-5486-b2f3-19a20fcc2a77', 'ri2uKTpw4lQ', 23, 258514, 269543, 'I go to the supermarket or to the shopping center because I like to buy the food that I will eat during the week.'),
    ('916b5854-0fda-5699-ae52-f30185d99602', 'ri2uKTpw4lQ', 24, 269543, 275879, 'So, today I have talked to you about what I normally do every week.'),
    ('e536ed42-d6b7-5599-905b-f857a56574b0', 'ri2uKTpw4lQ', 25, 275879, 286900, 'Sometimes I do other different things, like going to the mountains or visiting a new city, but this is just a typical week for me.'),
    ('212364ea-92c3-5c2b-acd6-43a52bf659af', 'ri2uKTpw4lQ', 26, 288270, 290421, 'What are your daily routines?'),
    ('9c34d72a-7f22-5e40-8f31-56793ba42911', 'ri2uKTpw4lQ', 27, 290421, 293290, 'What do you normally do at the weekend?'),
    ('7dccd035-6e3d-592b-8252-246df81446b0', 'ri2uKTpw4lQ', 28, 293290, 299630, 'Tell me what you normally do every week in the comment section for me to read.'),
    ('b5c8d5f1-5815-5e15-878f-122ccdb0c4a4', 'ri2uKTpw4lQ', 29, 299630, 314717, 'You can find the transcription and activities related to this topic in the description box.'),
    ('12a1e2dd-afdc-57ea-a624-f1369bfc7a05', 'ri2uKTpw4lQ', 30, 314717, 323683, 'Please like this video and subscribe to my channel if you liked the video.'),
    ('9efe50c8-9ec3-56e8-932d-14a538b4edaa', 'ri2uKTpw4lQ', 31, 323683, 326660, 'Thank you and see you next time!'),
    ('060eb998-8d69-5d09-b3c4-d8ba2fb19f7b', 'rrkrvAUbU9Y', 1, 24991, 31798, 'Something that, in many ways, I wish no one would ever know, but here I feel kind of obliged to reveal.'),
    ('04ff08ea-c12e-5429-a94f-09634fee931e', 'rrkrvAUbU9Y', 2, 45616, 50806, 'In America, law is a professional degree: after your university degree, you go on to law school.'),
    ('df217d39-c38f-5cbd-a1dd-175fe63e16ff', 'rrkrvAUbU9Y', 3, 79260, 85110, 'But today, against my better judgment, against the advice of my own wife,'),
    ('4c6014a0-43a3-5a9b-a0d2-8cced3fbf2c6', 'rrkrvAUbU9Y', 4, 85110, 91493, 'I want to try to dust off some of those legal skills -- what''s left of those legal skills.'),
    ('991a9fd7-2a50-5b55-b95a-a0d32b7768f1', 'rrkrvAUbU9Y', 5, 91493, 93389, 'I don''t want to tell you a story.'),
    ('ea4062b9-3f51-5efc-a373-0fd309de04da', 'rrkrvAUbU9Y', 6, 107903, 111379, 'So, ladies and gentlemen of the jury, take a look at this.'),
    ('1a438f64-16e6-540c-b3a3-f7a71a9c245d', 'rrkrvAUbU9Y', 7, 111379, 113710, 'This is called the candle problem.'),
    ('49ff4bc3-0cff-5ac7-bc2d-5fb16388371b', 'rrkrvAUbU9Y', 8, 113710, 115534, 'Some of you might know it.'),
    ('51e7e263-9c7e-5e19-96ec-f36dfa36e75b', 'rrkrvAUbU9Y', 9, 119110, 124265, 'He created this experiment that is used in many other experiments in behavioral science.'),
    ('c753b48b-ef20-52d0-997c-2730bdee1e48', 'rrkrvAUbU9Y', 10, 124265, 125547, 'And here''s how it works.'),
    ('83186307-4b5d-5ccb-a522-7aa8d7717e1a', 'rrkrvAUbU9Y', 11, 125547, 127110, 'Suppose I''m the experimenter.'),
    ('c5e41a03-43c3-5a19-a52e-f5cdb3ce6736', 'rrkrvAUbU9Y', 12, 127110, 128754, 'I bring you into a room.'),
    ('765ee8e9-4e69-521a-bbd9-c69a06e89fd2', 'rrkrvAUbU9Y', 13, 128754, 133002, 'I give you a candle, some thumbtacks and some matches.'),
    ('ee46b03e-e4c0-579b-be4a-9b0be0a906c3', 'rrkrvAUbU9Y', 14, 133002, 140260, 'And I say to you, "Your job is to attach the candle to the wall so the wax doesn''t drip onto the table."'),
    ('97f91f54-4f08-5765-aa69-f274a261014c', 'rrkrvAUbU9Y', 15, 140260, 141819, 'Now what would you do?'),
    ('03d865e3-318d-5a6c-8ddb-0a7a00be0c58', 'rrkrvAUbU9Y', 16, 141819, 145563, 'Many people begin trying to thumbtack the candle to the wall.'),
    ('fc7d27d7-5712-5ca0-897e-bd03c2dabe84', 'rrkrvAUbU9Y', 17, 146800, 154682, 'I saw somebody kind of make the motion over here -- some people have a great idea where they light the match,'),
    ('2c09311e-464a-5b47-8888-43a88636c480', 'rrkrvAUbU9Y', 18, 154682, 157635, 'melt the side of the candle, try to adhere it to the wall.'),
    ('5080e03f-cbd6-583f-83ac-833ade327c0b', 'rrkrvAUbU9Y', 19, 157635, 159065, 'It''s an awesome idea.'),
    ('0dd66505-c7aa-5794-a3fc-9dfd43a9cbdf', 'rrkrvAUbU9Y', 20, 160777, 166879, 'And eventually, after five or ten minutes, most people figure out the solution, which you can see here.'),
    ('41683a27-6354-5e3c-b7bc-30c43068e253', 'rrkrvAUbU9Y', 21, 166879, 170693, 'The key is to overcome what''s called functional fixedness.'),
    ('98a0e597-5ac7-59f1-8cd3-73ad01274620', 'rrkrvAUbU9Y', 22, 170693, 174681, 'You look at that box and you see it only as a receptacle for the tacks.'),
    ('cf0b3b85-c076-5b08-85b2-cb295097aa46', 'rrkrvAUbU9Y', 23, 174681, 178997, 'But it can also have this other function, as a platform for the candle.'),
    ('d7b481e0-274f-5818-b73a-53fb78464ea2', 'rrkrvAUbU9Y', 24, 178997, 180110, 'The candle problem.'),
    ('74636cba-3c8f-5a16-96a9-c47d34b7d05e', 'rrkrvAUbU9Y', 25, 180110, 188733, 'I want to tell you about an experiment using the candle problem, done by a scientist named Sam Glucksberg, who is now at Princeton University, US,'),
    ('3be5b1c4-8bc6-55b1-a2f7-66fa8995eab8', 'rrkrvAUbU9Y', 26, 188733, 192110, 'This shows the power of incentives.'),
    ('876d2d84-b478-5cb5-8744-be78dceea887', 'rrkrvAUbU9Y', 27, 192110, 197959, 'He gathered his participants and said: "I''m going to time you, how quickly you can solve this problem."'),
    ('f0580468-3ae5-58d1-a7b3-0fda9d5db966', 'rrkrvAUbU9Y', 28, 197959, 202110, 'To one group he said, "I''m going to time you to establish norms,'),
    ('67f67545-37ab-5dfd-88cd-8720db373f12', 'rrkrvAUbU9Y', 29, 202110, 206675, 'averages for how long it typically takes someone to solve this sort of problem."'),
    ('1eaef6b7-83df-5a7a-b81b-c971922558ca', 'rrkrvAUbU9Y', 30, 206675, 209236, 'To the second group he offered rewards.'),
    ('be40c8bb-3f7f-5e46-b941-22d51df12a8a', 'rrkrvAUbU9Y', 31, 221110, 226586, 'Now this is several years ago, adjusted for inflation, it''s a decent sum of money for a few minutes of work.'),
    ('3c527bfd-dccd-544b-b61d-3e42c06136ff', 'rrkrvAUbU9Y', 32, 226586, 228236, 'It''s a nice motivator.'),
    ('c55a1cbd-22ac-55d1-b952-648194d0e950', 'rrkrvAUbU9Y', 33, 241662, 243508, 'This makes no sense, right?'),
    ('ec15eed6-006e-56d1-a187-e0fe9431e88c', 'rrkrvAUbU9Y', 34, 243508, 244999, 'I mean, I''m an American.'),
    ('c465981f-6d74-5d23-a4f5-1936286a7937', 'rrkrvAUbU9Y', 35, 244999, 246635, 'I believe in free markets.'),
    ('e8e95aa7-543b-53c5-9c14-da888aa493fa', 'rrkrvAUbU9Y', 36, 246635, 249236, 'That''s not how it''s supposed to work, right?'),
    ('a46ce21a-ab61-573f-9bef-b196f99a4a00', 'rrkrvAUbU9Y', 37, 250318, 253940, 'If you want people to perform better, you reward them.'),
    ('01943d7e-2a58-5849-bb5d-02dc8197125e', 'rrkrvAUbU9Y', 38, 254257, 257236, 'Bonuses, commissions, their own reality show.'),
    ('dc95bb33-c177-5f07-a611-0292c38ae07f', 'rrkrvAUbU9Y', 39, 259972, 261379, 'That''s how business works.'),
    ('3ae75617-84c7-5de4-b9a7-754cbaef6cef', 'rrkrvAUbU9Y', 40, 261379, 263416, 'But that''s not happening here.'),
    ('94ae64e5-e80e-5f05-b053-9eb31bde7a9d', 'rrkrvAUbU9Y', 41, 263416, 271110, 'You''ve got an incentive designed to sharpen thinking and accelerate creativity, and it does just the opposite.'),
    ('37025062-cbb1-5d31-aabf-0112321084c8', 'rrkrvAUbU9Y', 42, 271110, 274110, 'It dulls thinking and blocks creativity.'),
    ('918a81fd-0e5a-5b0f-b341-3d3d23abf9ed', 'rrkrvAUbU9Y', 43, 274110, 277785, 'What''s interesting about this experiment is that it''s not an aberration.'),
    ('23aa9598-5e75-57a6-a15a-644bdf2f9e31', 'rrkrvAUbU9Y', 44, 283810, 290110, 'These contingent motivators -- if you do this, then you get that -- work in some circumstances.'),
    ('4da33742-3498-54be-bc88-0e9389dce26a', 'rrkrvAUbU9Y', 45, 290110, 295992, 'But for a lot of tasks, they actually either don''t work or, often, they do harm.'),
    ('edb1c543-79c7-5839-9f78-738907cdf3a8', 'rrkrvAUbU9Y', 46, 296798, 305268, 'This is one of the most robust findings in social science, and also one of the most ignored.'),
    ('46d8486d-47a0-58ba-bae8-00d193319c07', 'rrkrvAUbU9Y', 47, 305268, 313110, 'I spent the last couple of years looking at the science of human motivation, particularly the dynamics of extrinsic motivators and intrinsic motivators.'),
    ('c6c91a69-7668-53af-b9bb-b44ed391f87e', 'rrkrvAUbU9Y', 48, 313110, 315546, 'And I''m telling you, it''s not even close.'),
    ('96b9ab42-4254-5b15-b615-a3c956b27c2e', 'rrkrvAUbU9Y', 49, 315546, 321220, 'If you look at the science, there is a mismatch between what science knows and what business does.'),
    ('032f9777-871a-5ac4-a531-75366af22433', 'rrkrvAUbU9Y', 50, 321220, 329330, 'What''s alarming here is that our business operating system -- think of the set of assumptions and protocols beneath our businesses, how we motivate people,'),
    ('8f3a74dd-dab3-5601-a724-4eab415e65eb', 'rrkrvAUbU9Y', 51, 329330, 337554, 'how we apply our human resources-- it''s built entirely around these extrinsic motivators, around carrots and sticks.'),
    ('3275c64b-2e3d-5c03-9cec-5b5eb7bafc2d', 'rrkrvAUbU9Y', 52, 351725, 352932, 'Let me show you.'),
    ('3a80c351-9836-5609-89f1-887339f32c50', 'rrkrvAUbU9Y', 53, 352932, 359840, 'Glucksberg did another similar experiment, he presented the problem in a slightly different way, like this up here.'),
    ('726128c0-bc16-5960-a5da-bc12cc6d6595', 'rrkrvAUbU9Y', 54, 360612, 364038, 'Attach the candle to the wall so the wax doesn''t drip onto the table.'),
    ('1b77adf8-b3d5-5aac-bafd-8043e7bf11b9', 'rrkrvAUbU9Y', 55, 368879, 370480, 'What happened this time?'),
    ('276e2db9-b08e-5aaf-ab75-909969c40ed6', 'rrkrvAUbU9Y', 56, 371310, 377663, 'This time, the incentivized group kicked the other group''s butt.'),
    ('b552b4ed-ab00-5a8c-aa14-10d80e129bcc', 'rrkrvAUbU9Y', 57, 379364, 383677, 'Because when the tacks are out of the box, it''s pretty easy isn''t it?'),
    ('d9ea3f88-30c9-5d64-9691-ad0d46f88dc7', 'rrkrvAUbU9Y', 58, 387845, 397110, 'If-then rewards work really well for those sorts of tasks, where there is a simple set of rules and a clear destination to go to.'),
    ('efd5bc98-d572-5b21-9fea-7cdf9d51ae67', 'rrkrvAUbU9Y', 59, 397110, 403469, 'Rewards, by their very nature, narrow our focus, concentrate the mind; that''s why they work in so many cases.'),
    ('8cb42f87-7d18-5f74-829f-3d8cacf5ad47', 'rrkrvAUbU9Y', 60, 403469, 412006, 'So, for tasks like this, a narrow focus, where you just see the goal right there, zoom straight ahead to it, they work really well.'),
    ('3a0075b4-ab81-52bb-ae6a-a29de3408a9d', 'rrkrvAUbU9Y', 61, 412006, 416766, 'But for the real candle problem, you don''t want to be looking like this.'),
    ('820d1f62-acc7-56b5-a9eb-95de7e365d02', 'rrkrvAUbU9Y', 62, 416766, 418403, 'The solution is on the periphery.'),
    ('3c27f87c-4405-5daf-bb9f-ac60dc8a0360', 'rrkrvAUbU9Y', 63, 418403, 419920, 'You want to be looking around.'),
    ('9ef0133a-ae7d-50fa-bc40-537a2b5825d1', 'rrkrvAUbU9Y', 64, 419920, 424110, 'That reward actually narrows our focus and restricts our possibility.'),
    ('17cbf684-9218-5094-ad90-bbe5f8e3a1dc', 'rrkrvAUbU9Y', 65, 424110, 426229, 'Let me tell you why this is so important.'),
    ('add2a58a-dc2e-50e0-8f50-1f5f617ea065', 'rrkrvAUbU9Y', 66, 427286, 437911, 'In western Europe, in many parts of Asia, in North America, in Australia, white-collar workers are doing less of this kind of work,'),
    ('15e4c89b-bbcc-5fb4-9d54-1d1689860858', 'rrkrvAUbU9Y', 67, 437911, 440441, 'and more of this kind of work.'),
    ('70f2f6e5-54ba-54a7-8f7d-ac1da1322f07', 'rrkrvAUbU9Y', 68, 441975, 453703, 'That routine, rule-based, left-brain work -- certain kinds of accounting, financial analysis, computer programming -- has become fairly easy to outsource, fairly easy to automate.'),
    ('b84c7cf3-460a-5867-aadc-a3a3e537835c', 'rrkrvAUbU9Y', 69, 453703, 455903, 'Software can do it faster.'),
    ('6a0dae57-230b-5705-abd3-d95836b8a88c', 'rrkrvAUbU9Y', 70, 455903, 458252, 'Low-cost providers can do it cheaper.'),
    ('88ad8fca-6b3e-5698-b979-fc2ffccb3c2c', 'rrkrvAUbU9Y', 71, 458252, 465896, 'So what really matters are the more right-brained creative, conceptual kinds of abilities.'),
    ('35735abf-3bb4-5012-958c-87f1f4541bf4', 'rrkrvAUbU9Y', 72, 465896, 468301, 'Think about your own work.'),
    ('f2f1af29-7fde-54f8-a2a2-c5c92f9e5bf2', 'rrkrvAUbU9Y', 73, 468301, 470195, 'Think about your own work.'),
    ('8c4bdfef-b0bd-50cc-ae5d-5adc6c5345b8', 'rrkrvAUbU9Y', 74, 470983, 478022, 'Are the problems that you face, or even the problems we''ve been talking about here, do they have a clear set of rules,'),
    ('46314f00-3edf-51c4-9325-2b63468107cd', 'rrkrvAUbU9Y', 75, 478022, 479633, 'and a single solution?'),
    ('9ddbcc2e-3ed7-58b8-9483-8e107e008081', 'rrkrvAUbU9Y', 76, 479633, 482110, 'No. The rules are mystifying.'),
    ('9295a37b-0c25-57a1-8530-436a7463228e', 'rrkrvAUbU9Y', 77, 482110, 487110, 'The solution, if it exists at all, is surprising and not obvious.'),
    ('e5a3d93b-1da9-55b4-8ab3-c3cfd190590a', 'rrkrvAUbU9Y', 78, 487110, 494110, 'Everybody in this room is dealing with their own version of the candle problem.'),
    ('7d43a6ec-ef9a-5c6c-8898-0a1e2d383809', 'rrkrvAUbU9Y', 79, 494110, 508105, 'And for candle problems of any kind, in any field, those if-then rewards, the things around which we''ve built so many of our businesses, don''t work!'),
    ('5934fca4-5958-58c5-9b6d-78649bcf16fa', 'rrkrvAUbU9Y', 80, 508105, 510585, 'It makes me crazy.'),
    ('5735de07-4296-587d-a899-c5e847506852', 'rrkrvAUbU9Y', 81, 510585, 512545, 'And here''s the thing.'),
    ('bb4afd7a-7298-5ef4-bf57-0bb3109d6901', 'rrkrvAUbU9Y', 82, 512545, 514751, 'This is not a feeling.'),
    ('40d47a6d-011b-5fc7-b933-681f0a534d90', 'rrkrvAUbU9Y', 83, 516184, 518924, 'I''m a lawyer; I don''t believe in feelings.'),
    ('1f97c647-5017-56cd-bb77-bfd6e7a90a9e', 'rrkrvAUbU9Y', 84, 518924, 522591, 'This is not a philosophy.'),
    ('a6a48deb-9854-546d-8afd-6e7d45718157', 'rrkrvAUbU9Y', 85, 522591, 525003, 'I''m an American; I don''t believe in philosophy.'),
    ('ae8dab3d-b905-5494-838d-30a97d9e2645', 'rrkrvAUbU9Y', 86, 527475, 534675, 'This is a fact -- or, as we say in my hometown of Washington, D.C., a true fact.'),
    ('84078455-e0af-5079-a1e4-d8b02bd305d0', 'rrkrvAUbU9Y', 87, 540835, 542501, 'Let me give you an example.'),
    ('18e36f8c-49c3-50bc-b5f5-2eecc0f3c438', 'rrkrvAUbU9Y', 88, 542501, 544110, 'Let me marshal the evidence here.'),
    ('012e0689-c7b6-56bd-9e70-81983ce1fb12', 'rrkrvAUbU9Y', 89, 544110, 546372, 'I''m not telling a story, I''m making a case.'),
    ('83bb1a3b-ed39-56f9-b891-5adb8cb5ee43', 'rrkrvAUbU9Y', 90, 551941, 555436, 'he and three colleagues did a study of some MIT students.'),
    ('d33a3e63-209e-5556-8d46-0a4308ea8bdd', 'rrkrvAUbU9Y', 91, 555436, 562412, 'They gave these MIT students a bunch of games, games that involved creativity, and motor skills, and concentration.'),
    ('3c60c272-b899-51a4-aa3d-6a9e3e99fbe8', 'rrkrvAUbU9Y', 92, 562412, 570825, 'And the offered them, for performance, three levels of rewards: small reward, medium reward, large reward.'),
    ('024d7e34-b69e-5012-b6dc-11f5d9604f68', 'rrkrvAUbU9Y', 93, 570825, 575112, 'If you do really well you get the large reward, on down.'),
    ('7bc74bc2-38be-5766-9903-3bcb844d1dd3', 'rrkrvAUbU9Y', 94, 576344, 584957, 'As long as the task involved only mechanical skill bonuses worked as they would be expected: the higher the pay, the better the performance.'),
    ('6c48a8c8-8d64-59a3-a0af-15b5fde0a96f', 'rrkrvAUbU9Y', 95, 586006, 597206, 'But once the task called for even rudimentary cognitive skill, a larger reward led to poorer performance.'),
    ('88b00153-2f36-58ed-9ac8-6b997b6d1c66', 'rrkrvAUbU9Y', 96, 597206, 600539, 'Then they said, "Let''s see if there''s any cultural bias here.'),
    ('66426b9e-ba3c-5925-bd2c-513b1e7b0486', 'rrkrvAUbU9Y', 97, 600539, 602516, 'Let''s go to Madurai, India and test it."'),
    ('f3310f9c-3297-5a38-bf1e-9bbedbfd35d9', 'rrkrvAUbU9Y', 98, 602516, 604110, 'Standard of living is lower.'),
    ('c9a2970b-8a4c-5038-8c9b-35e6127f4632', 'rrkrvAUbU9Y', 99, 604110, 609102, 'In Madurai, a reward that is modest in North American standards, is more meaningful there.'),
    ('127484e4-6de5-5165-ba50-2285e33d5571', 'rrkrvAUbU9Y', 100, 610502, 613361, 'A bunch of games, three levels of rewards.'),
    ('3d86b0cb-1c9b-509d-8860-a019de7fd590', 'rrkrvAUbU9Y', 101, 615251, 620879, 'People offered the medium level of rewards did no better than people offered the small rewards.'),
    ('40b30a46-2b21-5c58-9460-f5a3e8165b6b', 'rrkrvAUbU9Y', 102, 620879, 627028, 'But this time, people offered the highest rewards, they did the worst of all.'),
    ('86a0d77c-de93-5ff6-b415-8edb175b9c7c', 'rrkrvAUbU9Y', 103, 628927, 635942, 'In eight of the nine tasks we examined across three experiments, higher incentives led to worse performance.'),
    ('d0732f33-6910-5e7f-856d-d4edbb1ebd90', 'rrkrvAUbU9Y', 104, 637584, 643584, 'Is this some kind of touchy-feely socialist conspiracy going on here?'),
    ('f0943df1-5d29-5f47-a56f-846b68129965', 'rrkrvAUbU9Y', 105, 643584, 649110, 'No, these are economists from MIT, from Carnegie Mellon, from the University of Chicago.'),
    ('3e4552f8-babd-5bab-9984-d7db52ab97be', 'rrkrvAUbU9Y', 106, 649110, 651755, 'Do you know who sponsored this research?'),
    ('b3ea7205-9e9f-5d1b-90dc-cb85d3fa5a7a', 'rrkrvAUbU9Y', 107, 651755, 655899, 'The Federal Reserve Bank of the United States.'),
    ('76f250a9-ad67-57bc-bd9a-9593ff6adece', 'rrkrvAUbU9Y', 108, 655899, 657869, 'That''s the American experience.'),
    ('5800a269-c066-5844-93f3-d66239fd5459', 'rrkrvAUbU9Y', 109, 666578, 673547, 'Training ground for great economic thinkers like George Soros, and Friedrich Hayek, and Mick Jagger.'),
    ('67d3ca41-a47e-53a6-b9fb-1a90601cc255', 'rrkrvAUbU9Y', 110, 692886, 698110, 'There is a mismatch between what science knows and what business does.'),
    ('e291f897-517e-501a-921e-0400a487adcb', 'rrkrvAUbU9Y', 111, 698110, 707110, 'And what worries me, as we stand here in the rubble of the economic collapse, is that too many organizations are making their decisions,'),
    ('8f113c25-a020-55a7-8f21-af4bf4038bce', 'rrkrvAUbU9Y', 112, 707110, 717783, 'their policies about talent and people, based on assumptions that are outdated, unexamined, and rooted more in folklore than in science.'),
    ('1e6412a3-0afc-5152-9ee4-10f95bae9b23', 'rrkrvAUbU9Y', 113, 725698, 736432, 'the solution is not to do more of the wrong things, to entice people with a sweeter carrot, or threaten them with a sharper stick.'),
    ('b031d9d6-9604-5379-be9c-1f37daaedd2c', 'rrkrvAUbU9Y', 114, 736432, 738110, 'We need a whole new approach.'),
    ('14fd1eee-0914-57a6-bea6-b951f3171bf4', 'rrkrvAUbU9Y', 115, 738110, 743322, 'The good news is that the scientists who''ve been studying motivation have given us this new approach.'),
    ('7799ae03-d8a4-5bb6-99eb-fa4822588a47', 'rrkrvAUbU9Y', 116, 743322, 746441, 'It''s built much more around intrinsic motivation.'),
    ('5066383e-6f9d-53fd-bf25-e9e5b3b2dd8a', 'rrkrvAUbU9Y', 117, 746441, 752507, 'Around the desire to do things because they matter, because we like it, they''re interesting, or part of something important.'),
    ('b098dbdf-a8e9-5d93-aa05-7c5f46ce7782', 'rrkrvAUbU9Y', 118, 752507, 761236, 'And to my mind, that new operating system for our businesses revolves around three elements: autonomy, mastery and purpose.'),
    ('e891337e-05f8-560b-baad-5b699eef4631', 'rrkrvAUbU9Y', 119, 774327, 779110, 'These are the building blocks of an entirely new operating system for our businesses.'),
    ('9c2b943a-4948-508e-88cf-3ece48e2b2d6', 'rrkrvAUbU9Y', 120, 779110, 781821, 'I want to talk today only about autonomy.'),
    ('9f5ffb3a-3dcd-54a0-afb4-405e1651e4f9', 'rrkrvAUbU9Y', 121, 786110, 788428, 'Management did not emanate from nature.'),
    ('ec5f9e9c-5d89-5eda-a618-7ecea517286c', 'rrkrvAUbU9Y', 122, 788428, 792110, 'Management is not a tree, it''s a television set.'),
    ('ccb4447e-ccba-5c1b-a0e3-f9e0e8a8f45f', 'rrkrvAUbU9Y', 123, 792110, 794358, 'Somebody invented it.'),
    ('e8acdeb6-622f-54f7-8087-9bf789dfe93a', 'rrkrvAUbU9Y', 124, 794358, 796382, 'It doesn''t mean it''s going to work forever.'),
    ('f34ebcd6-4613-51a2-87c3-8b27132943a6', 'rrkrvAUbU9Y', 125, 796382, 798413, 'Management is great.'),
    ('098cad98-c601-547e-bf31-5d8045364836', 'rrkrvAUbU9Y', 126, 798413, 802110, 'Traditional notions of management are great if you want compliance.'),
    ('ed909789-720c-5dc1-b189-82db1a1c828e', 'rrkrvAUbU9Y', 127, 802110, 805317, 'But if you want engagement, self-direction works better.'),
    ('59bd1e61-fec2-547e-a4d7-61930b13a0ac', 'rrkrvAUbU9Y', 128, 805317, 809381, 'Some examples of some kind of radical notions of self-direction.'),
    ('d50a90d2-f867-56f1-a55b-f64126691913', 'rrkrvAUbU9Y', 129, 809381, 815841, 'You don''t see a lot of it, but you see the first stirrings of something really interesting going on,'),
    ('54322662-f877-53c8-925e-22594c947815', 'rrkrvAUbU9Y', 130, 815841, 823941, 'what it means is paying people adequately and fairly, absolutely -- getting the issue of money off the table, and then giving people lots of autonomy.'),
    ('a7301288-dbff-55d6-bb22-7304fbb2c30c', 'rrkrvAUbU9Y', 131, 825110, 828205, 'How many of you have heard of the company Atlassian?'),
    ('72a75e0b-1214-5913-a4a7-b8a41b6090b4', 'rrkrvAUbU9Y', 132, 829578, 831236, 'It looks like less than half.'),
    ('767d6c19-2599-51ac-b02d-0dbbe22cf9da', 'rrkrvAUbU9Y', 133, 832539, 837110, 'Atlassian is an Australian software company.'),
    ('001cd66f-1f6a-525a-b38b-e55fee0bbbe2', 'rrkrvAUbU9Y', 134, 837110, 839231, 'And they do something incredibly cool.'),
    ('677e3236-bf89-5259-900a-dd76059d8aa9', 'rrkrvAUbU9Y', 135, 845903, 848037, 'as long as it''s not part of your regular job.'),
    ('88d79504-ad15-5908-94f5-a11e5b72f480', 'rrkrvAUbU9Y', 136, 848037, 849451, 'Work on anything you want."'),
    ('0ce12930-120c-5814-b94e-b3491646edfd', 'rrkrvAUbU9Y', 137, 849451, 854704, 'Engineers use this time to come up with a cool patch for code, come up with an elegant hack.'),
    ('826d9487-fec9-5e6a-b649-1800e2ba3b64', 'rrkrvAUbU9Y', 138, 854704, 860438, 'Then they present all of the stuff that they''ve developed to their teammates, to the rest of the company,'),
    ('59f2ed67-1bc3-5925-ac92-dd26834de441', 'rrkrvAUbU9Y', 139, 860438, 864414, 'in this wild and woolly all-hands meeting at the end of the day.'),
    ('3bbaeeb2-dcf9-5487-af9f-f784485e5b58', 'rrkrvAUbU9Y', 140, 864414, 866633, 'Being Australians, everybody has a beer.'),
    ('d4c4c64f-3622-5f8b-88e1-2cbb5ef2ec02', 'rrkrvAUbU9Y', 141, 866633, 868802, 'They call them FedEx Days.'),
    ('db7c7dcf-7066-52dd-93a1-a31f87c60386', 'rrkrvAUbU9Y', 142, 871625, 874162, 'Because you have to deliver something overnight.'),
    ('86801072-187e-57aa-8cfc-9e12c2db8e23', 'rrkrvAUbU9Y', 143, 874927, 876518, 'It''s pretty; not bad.'),
    ('10d7ee6e-431d-536a-803e-b36bbdd04efa', 'rrkrvAUbU9Y', 144, 876518, 879336, 'It''s a huge trademark violation, but it''s pretty clever.'),
    ('19ff0ded-9650-577d-99f6-5b5568b52a17', 'rrkrvAUbU9Y', 145, 880571, 886236, 'That one day of intense autonomy has produced a whole array of software fixes that might never have existed.'),
    ('03cad4d1-7036-508a-a26b-cb23dfd3e8d5', 'rrkrvAUbU9Y', 146, 896531, 900459, 'They have autonomy over their time, their task, their team, their technique.'),
    ('255f7882-ba7f-5028-815d-ed44453c7c0f', 'rrkrvAUbU9Y', 147, 900459, 902562, 'Radical amounts of autonomy.'),
    ('334d441f-2bff-57c5-ba2f-4c928fcf10df', 'rrkrvAUbU9Y', 148, 911244, 914110, 'things like Gmail, Orkut, Google News.'),
    ('fcf95c3f-a388-5515-946c-2237d8b3dd2b', 'rrkrvAUbU9Y', 149, 914110, 923041, 'Let me give you an even more radical example of it: something called the Results Only Work Environment, created by two American consultants,'),
    ('bf7a50e0-03c2-5e43-a4a0-6aad42ae54fa', 'rrkrvAUbU9Y', 150, 923041, 925744, 'in place at a dozen companies around North America.'),
    ('073f2f68-6f8a-5d65-95ca-8812018b2d8a', 'rrkrvAUbU9Y', 151, 925744, 928499, 'In a ROWE people don''t have schedules.'),
    ('87e3f4f5-14a7-5ff5-b453-214ce1769a31', 'rrkrvAUbU9Y', 152, 929678, 931349, 'They show up when they want.'),
    ('f4405716-c5f9-5844-831a-efc000597f63', 'rrkrvAUbU9Y', 153, 931349, 935427, 'They don''t have to be in the office at a certain time, or any time.'),
    ('a63df1ad-f23e-50dd-addf-5a907f3683be', 'rrkrvAUbU9Y', 154, 935427, 937396, 'They just have to get their work done.'),
    ('7a67c9af-ca19-52a3-a645-95ae99ace6b0', 'rrkrvAUbU9Y', 155, 937396, 941705, 'How they do it, when they do it, where they do it, is totally up to them.'),
    ('4f65114e-ee9d-5a5b-804e-eae0bd9a9eb7', 'rrkrvAUbU9Y', 156, 942594, 946074, 'Meetings in these kinds of environments are optional.'),
    ('d5184332-ba6d-5e07-85e8-f288bfba263e', 'rrkrvAUbU9Y', 157, 948474, 957110, 'Almost across the board, productivity goes up, worker engagement goes up, worker satisfaction goes up, turnover goes down.'),
    ('3c4a924f-c8d7-5143-aa88-3febab4fa913', 'rrkrvAUbU9Y', 158, 957110, 961746, 'Autonomy, mastery and purpose, the building blocks of a new way of doing things.'),
    ('7421a970-653f-599c-96ae-778bae4d4034', 'rrkrvAUbU9Y', 159, 961746, 966719, 'Some of you might look at this and say, "Hmm, that sounds nice, but it''s Utopian."'),
    ('874b1846-e00e-5b74-9363-a825cd247350', 'rrkrvAUbU9Y', 160, 967468, 969098, 'And I say, "Nope.'),
    ('e61692bc-ad91-5b43-ac9c-c55fa56af4c1', 'rrkrvAUbU9Y', 161, 970475, 972193, 'I have proof."'),
    ('4ed2a347-c007-5133-baaf-f8ab456be701', 'rrkrvAUbU9Y', 162, 976110, 983324, 'They had deployed all the right incentives, They paid professionals to write and edit thousands of articles.'),
    ('3a80ae9f-db7a-5839-bc06-a67093fb5dd5', 'rrkrvAUbU9Y', 163, 983324, 988345, 'Well-compensated managers oversaw the whole thing to make sure it came in on budget and on time.'),
    ('6f4a41d6-7430-5da3-a522-9474b10e48f0', 'rrkrvAUbU9Y', 164, 990110, 992638, 'A few years later, another encyclopedia got started.'),
    ('00ccacdb-91c5-53b1-af02-68017b5bd106', 'rrkrvAUbU9Y', 165, 992638, 994185, 'Different model, right?'),
    ('cfe14b08-4351-59d8-807b-b97b01ac350a', 'rrkrvAUbU9Y', 166, 995456, 997140, 'Do it for fun.'),
    ('6105379d-0684-5e7c-9105-cd29440d790e', 'rrkrvAUbU9Y', 167, 997140, 999857, 'No one gets paid a cent, or a euro or a yen.'),
    ('163cb0d0-50ba-5876-98ba-b94c1aa77960', 'rrkrvAUbU9Y', 168, 1001206, 1003279, 'Do it because you like to do it.'),
    ('f262e62a-ca1a-5652-ab4c-6a4739d0aba7', 'rrkrvAUbU9Y', 169, 1010982, 1014053, 'If they went head to head, who would win?"'),
    ('2d8f92d7-b873-594b-89ec-17aa157fbfe3', 'rrkrvAUbU9Y', 170, 1022657, 1025380, 'This is the titanic battle between these two approaches.'),
    ('d8a0798f-0676-50e1-9dfb-3f3e50aeebb5', 'rrkrvAUbU9Y', 171, 1025380, 1028597, 'This is the Ali-Frazier of motivation, right?'),
    ('3e08a614-2238-5594-8260-d16ef98f4e71', 'rrkrvAUbU9Y', 172, 1030335, 1033528, 'Intrinsic motivators versus extrinsic motivators.'),
    ('70825739-6bb1-5080-ab87-edd3e669f1a2', 'rrkrvAUbU9Y', 173, 1033528, 1037691, 'Autonomy, mastery and purpose, versus carrot and sticks, and who wins?'),
    ('c6690207-9c0a-571e-a8ea-f2c7a1843cbd', 'rrkrvAUbU9Y', 174, 1037691, 1041245, 'Intrinsic motivation, autonomy, mastery and purpose, in a knockout.'),
    ('3d44a339-f1b9-513d-aa71-6f7580bc71f3', 'rrkrvAUbU9Y', 175, 1041245, 1042395, 'Let me wrap up.'),
    ('a60fb654-4931-54ac-bc69-33207624237e', 'rrkrvAUbU9Y', 176, 1044633, 1047960, 'There is a mismatch between what science knows and what business does.'),
    ('60fe0921-afc2-5a7c-b22e-1f2b3ce81a28', 'rrkrvAUbU9Y', 177, 1047960, 1049697, 'Here is what science knows.'),
    ('c2b2c5b2-f302-514a-8bfa-6f4b931521b3', 'rrkrvAUbU9Y', 178, 1071110, 1073110, 'The drive to do things cause they matter.'),
    ('579081d9-e35a-5731-bcff-d50ccfe7dada', 'rrkrvAUbU9Y', 179, 1073110, 1075110, 'And here''s the best part.'),
    ('4368807f-76e4-56ed-b374-fa4b206562cb', 'rrkrvAUbU9Y', 180, 1075110, 1076354, 'We already know this.'),
    ('e65f8922-a198-54dd-8848-c9f9eb87050d', 'rrkrvAUbU9Y', 181, 1076354, 1079054, 'The science confirms what we know in our hearts.'),
    ('32fd7717-419a-5798-a643-5ac4bd1de91c', 'rrkrvAUbU9Y', 182, 1088490, 1099943, 'if we get past this lazy, dangerous, ideology of carrots and sticks, we can strengthen our businesses, we can solve a lot of those candle problems,'),
    ('5101560b-b8ec-502e-812f-038db9e60b8a', 'rrkrvAUbU9Y', 183, 1099943, 1105887, 'and maybe, maybe -- we can change the world.'),
    ('15f95a06-da23-548f-bcc6-82e90c6c60f8', 'rrkrvAUbU9Y', 184, 1105887, 1107342, 'I rest my case.'),
    ('5d0bdb31-5ec1-50d7-a281-178e182affa9', 'xQ156y4TtJs', 1, 35148, 39509, 'people began foraging for wild coffee in the forest undergrowth.'),
    ('550fa391-c1fc-5764-b208-f19dac7d3ea0', 'xQ156y4TtJs', 2, 39652, 48895, 'The reason coffee plants are equipped with lots of caffeine might be because it makes them unattractive to herbivores or more attractive to pollinators.'),
    ('5f2b5027-874b-5b55-813c-e045fc09350f', 'xQ156y4TtJs', 3, 48995, 54917, 'But either way, people caught on to coffee''s advantages and began making tea from its leaves;'),
    ('0074eb6f-b3e0-5c90-89cc-67764fa751dd', 'xQ156y4TtJs', 4, 54917, 64911, 'combining its berries with butter and salt for a sustaining snack; and drying, roasting, and simmering its cherries into an energizing elixir.'),
    ('64ad1d2c-1c57-5424-a17b-f10b18a4c293', 'xQ156y4TtJs', 5, 73460, 83094, 'Upon returning from a visit to Ethiopia, a Sufi leader recommended that worshippers in Yemen use coffee during ritual chants and dances.'),
    ('85d36538-221c-56f2-a1f8-d5c9812dfec5', 'xQ156y4TtJs', 6, 83196, 90977, 'Soon enough, people within the Ottoman Empire began roasting and grinding the beans to yield a darker, bolder beverage.'),
    ('f528c2a8-bdf0-5b95-bedb-0f45ed31a6f3', 'xQ156y4TtJs', 7, 97109, 105409, 'But authorities grew concerned about whether coffee''s influence was innocent or intoxicating, and if Muslims should be allowed to drink it.'),
    ('b4ecdddc-3805-5af8-9ed0-c8b0053f8973', 'xQ156y4TtJs', 8, 111414, 123386, 'Scholars finally deemed it permissible, so coffeehouses sprang up in Damascus, Istanbul, and beyond, where clientele could sip coffee, smoke, and enjoy a variety of entertainment.'),
    ('e2fed68d-936e-5c87-9346-e1b57041b3ff', 'xQ156y4TtJs', 9, 131661, 135606, 'which became known in other parts of the world as Mocha.'),
    ('cc1eb73e-fa87-54ff-8609-67ad29a707cf', 'xQ156y4TtJs', 10, 135957, 143280, 'But coffee was eventually transported— or smuggled— into India, and soon took root in Java and beyond.'),
    ('e9622697-b8ef-569a-94d1-bbac1572885b', 'xQ156y4TtJs', 11, 179125, 182861, 'In France, people began mixing coffee with milk and sugar.'),
    ('2908156a-3cb7-531d-b04e-9244b10d1c03', 'xQ156y4TtJs', 12, 193931, 200211, 'Granted, these were likely small servings of comparatively weak coffee— but still, impressive.'),
    ('9743046d-25c2-5f5c-b632-9473108f412f', 'xQ156y4TtJs', 13, 200229, 211098, 'Meanwhile, European empires began profiting off coffee-growing, establishing enslaved or exploited workforces in Asia, Latin America, and the Caribbean.'),
    ('d04b4cde-7756-546b-ab7d-5d9a72c34578', 'xQ156y4TtJs', 14, 211532, 222860, 'As cultivation boomed in Latin America, fueled by slavery, growers displaced Indigenous populations and burned forests to establish ever-expanding plantations.'),
    ('8ade829c-8570-519a-b151-0bb28e8b5ee0', 'xQ156y4TtJs', 15, 228716, 234914, 'That same year, the Milan World''s Fair showcased the first commercial espresso machine.'),
    ('2f6b4f7b-8b9e-5bd1-913b-db2f8ebcdfad', 'xQ156y4TtJs', 16, 234972, 240878, 'And alongside the development of industrial roasting equipment came various coffee brands.'),
    ('a96b4cd0-8c7d-527b-9307-cbf020bc2b01', 'xQ156y4TtJs', 17, 247401, 252597, 'As African countries cut colonial ties, many ramped up coffee production.'),
    ('b645cc3e-73fc-54f5-8536-4936223ba19b', 'xQ156y4TtJs', 18, 252657, 259855, 'And coffee drinking also later made inroads in East Asia, especially as canned, pre-prepared beverages.'),
    ('880299b6-5299-56b4-aefc-6272db679acd', 'xQ156y4TtJs', 19, 260373, 271242, 'In more recent decades, specialty coffees with an emphasis on quality beans and brewing methods grew popular and propelled farms in Central America and East Africa.'),
    ('08a2152e-5b9e-522d-a897-21b4975f47a3', 'xQ156y4TtJs', 20, 271425, 278915, 'Yet coffee workers worldwide continued to endure inhumane conditions and insufficient compensation.'),
    ('e72f888e-6aca-57f7-9ec3-32d006a9b5d7', 'xQ156y4TtJs', 21, 278933, 287233, 'This motivated certification efforts for coffee production that met ethical standards, including minimum wage and sustainable farming.'),
    ('ecb3a3ef-0ede-54fc-89a0-e27652344dd2', 'xQ156y4TtJs', 22, 287233, 290009, 'But issues still loom over the industry.'),
    ('9487262a-5861-53c7-9897-a862159c2ede', 'xQ156y4TtJs', 23, 290152, 298411, 'And because of climate change, the equatorial "Bean Belt" where coffee thrives is projected to shrink in upcoming decades.'),
    ('af407d04-d213-59c6-8d05-10a22b6f31ad', 'xQ156y4TtJs', 24, 298411, 301372, 'It''s unclear exactly what this might look like.'),
    ('e007e3fd-d220-5c9b-98d5-24f35587ee30', 'xQ156y4TtJs', 25, 301372, 309362, 'But scientists are investigating possibilities like resilient coffee hybrids that might help weather the unpredictable future—'),
    ('36dfc67f-39ea-5192-8592-1adb39037623', 'xQ156y4TtJs', 26, 309463, 315619, 'all to protect the beverage that''s become a cherished part of daily rituals worldwide.'),
    ('04a81b3b-8428-5ed3-be86-0aaae3739a83', 'xoblutORPNA', 1, 35630, 40160, 'The story thing turns out to be one of the better, less bullshitty conventions of the genre,'),
    ('482536bb-bcf0-51f3-8489-709cf5b361f4', 'xoblutORPNA', 2, 40710, 47201, 'but if you''re worried that I plan to present myself here as the wise, older fish explaining what water is to you younger fish,'),
    ('9e005927-16cf-50f5-9b05-975e630a7678', 'xoblutORPNA', 3, 47201, 48220, 'please don''t be.'),
    ('d1ace835-c958-5812-b59d-2e1b33ccb305', 'xoblutORPNA', 4, 63510, 69800, 'But the fact is that in the day to day trenches of adult existence, banal platitudes can have a life or death importance;'),
    ('4a648423-697f-5aea-bbb1-f03dada993f4', 'xoblutORPNA', 5, 70570, 74100, 'or so I wish to suggest to you on this dry and lovely morning.'),
    ('c228a149-ce41-56dd-a961-eae8c007d6b4', 'xoblutORPNA', 6, 90470, 94880, 'So let''s talk about the single most pervasive cliché in the commencement speech genre,'),
    ('cd738e46-0445-5b59-bfb0-d4a877bda762', 'xoblutORPNA', 7, 95110, 100969, 'which is that a liberal arts education is not so much about filling you up with knowledge as it is about, quote,'),
    ('eb581833-32f8-5835-b0d9-f3a490f65137', 'xoblutORPNA', 8, 100969, 102520, 'teaching you how to think.'),
    ('f060a821-fa9c-54d5-9fa8-0623d9458818', 'xoblutORPNA', 9, 104010, 107200, 'If you''re like me, as a student, you''ve never liked hearing this,'),
    ('cb7e2c80-ed89-5226-b0c2-23d07233ad63', 'xoblutORPNA', 10, 107390, 111860, 'And you tend to feel a bit insulted by the claim that you''ve needed anybody to teach you how to think,'),
    ('1ef86c83-4f4b-5cab-80c0-f822979255b9', 'xoblutORPNA', 11, 112310, 117299, 'Since the fact that you even got admitted to a college this good seems like proof that you already know how to think.'),
    ('fb32fc02-ccca-5bef-b543-b8a21ea8a7f4', 'xoblutORPNA', 12, 120350, 124700, 'But I''m going to posit to you that the liberal arts cliché turns out not to be insulting at all,'),
    ('b15c0e6d-2006-5475-bdca-9760a3be93fe', 'xoblutORPNA', 13, 125070, 132520, 'Because the really significant education in thinking that we''re supposed to get in a place like this isn''t really about the capacity to think,'),
    ('46e8010f-340e-5999-b945-3a5d0ebfd15d', 'xoblutORPNA', 14, 132750, 135260, 'but rather about the choice of what to think about.'),
    ('3bd36b70-0a32-5714-baf8-7dcb1096d4e0', 'xoblutORPNA', 15, 136410, 143336, 'If your total freedom of choice regarding what to think about seems too obvious to waste time discussing, I''d ask you to think about fish,'),
    ('54b98673-0862-54fb-873b-76618f5c6bdc', 'xoblutORPNA', 16, 143336, 149600, 'and water and to bracket, for just a few minutes, your skepticism about the value of the totally obvious.'),
    ('11005fbe-c42e-5c07-87bf-a6841aedf655', 'xoblutORPNA', 17, 153810, 161200, 'There are these two guys sitting together in a bar in the remote Alaskan wilderness, one of the guys is religious the other''s an atheist.'),
    ('ce3372ac-aeae-5df4-9eea-93028a21918b', 'xoblutORPNA', 18, 161530, 167200, 'And the two are arguing about the existence of God with that special intensity that comes after about after the fourth beer.'),
    ('8aafb25f-f42c-5bbf-88c4-39a5c6053ec7', 'xoblutORPNA', 19, 173370, 177160, 'It''s not like I have never experimented with the whole God and prayer thing.'),
    ('b9112e22-14aa-593b-ad85-a55b533965ac', 'xoblutORPNA', 20, 177830, 181179, 'Just last month I got cut away from camp in that terrible blizzard.'),
    ('04eeff9a-7980-5eb4-b8cd-03023a6935e4', 'xoblutORPNA', 21, 181470, 184119, 'And I was totally lost, and I couldn''t see a thing.'),
    ('8404b4d3-e7d3-5677-8716-608030095775', 'xoblutORPNA', 22, 184290, 185679, 'And it was fifty below.'),
    ('8a484511-d1bc-5288-b683-daecce024295', 'xoblutORPNA', 23, 190262, 193580, 'I''m lost in this blizzard, and I''m gonna die if you don''t help me."'),
    ('1104196a-6672-5ff2-a04d-2598f1fd3987', 'xoblutORPNA', 24, 194670, 198919, 'And now, in the bar, the religious guy looks at the atheist all puzzled.'),
    ('df391e79-a523-52e3-9fea-e03c5afb9b1e', 'xoblutORPNA', 25, 199270, 203979, '"Well then you must believe now," he says, "After all, here you are, alive."'),
    ('b8620534-2dbb-54b1-8949-03a7ba2d1670', 'xoblutORPNA', 26, 205070, 206602, 'The atheist just rolls his eyes.'),
    ('8ee31287-7eea-5acc-b9c5-dd3ea0f48e3f', 'xoblutORPNA', 27, 206602, 212140, '"No, man, all that was was a couple Eskimos happened to come wandering by and they showed me the way back to camp."'),
    ('b772d25b-f888-562a-9c97-58c01f4cdb8d', 'xoblutORPNA', 28, 213850, 217779, 'It''s easy to run this story through a kind of standard liberal arts analysis:'),
    ('e0f8669d-38a0-583f-ada9-feac35bdd74c', 'xoblutORPNA', 29, 218510, 222880, 'the exact same experience can mean two totally different things to two different people,'),
    ('e71d6038-e8e2-507f-b01d-aba707703db7', 'xoblutORPNA', 30, 223050, 228480, 'given those people''s two different belief templates and two different ways of constructing meaning from experience.'),
    ('cea01631-c626-57d0-9d89-14b057a8352f', 'xoblutORPNA', 31, 229350, 232420, 'Because we prize tolerance and diversity of belief,'),
    ('360481f8-74b7-5082-9bcd-f441b62b42ef', 'xoblutORPNA', 32, 232890, 239940, 'nowhere in our liberal arts analysis do we want to claim that one guy''s interpretation is true and the other guy''s is false or bad.'),
    ('3ee09ff3-bacb-5404-bd1e-0810905ecd7f', 'xoblutORPNA', 33, 240910, 246780, 'Which is fine, except we also never end up talking about just where these individual templates and beliefs come from.'),
    ('b07e058d-2b0e-5473-92d1-7cd12ae61b30', 'xoblutORPNA', 34, 247210, 249879, 'Meaning, where they come from INSIDE the two guys.'),
    ('5ec45a53-3683-5844-835b-a04bd4a66c82', 'xoblutORPNA', 35, 250710, 258979, 'As if a person''s most basic orientation toward the world, and the meaning of his experience were somehow just hard-wired, like height or shoe-size;'),
    ('05390474-c954-53f4-9052-6da24456e623', 'xoblutORPNA', 36, 259750, 262740, 'or automatically absorbed from the culture, like language.'),
    ('31f0d0cd-1ddb-5076-8213-e94ddaf5da86', 'xoblutORPNA', 37, 263730, 268760, 'As if how we construct meaning were not actually a matter of personal, intentional choice.'),
    ('f3c19b3c-bc63-5d5e-a659-b46d61a4a7f6', 'xoblutORPNA', 38, 275510, 277120, 'Plus, there''s the matter of arrogance.'),
    ('492653f0-e4b5-5fa1-a2d3-83b9d289c609', 'xoblutORPNA', 39, 277570, 285160, 'The nonreligious guy is so totally certain, in his dismissal of the possibility that the passing Eskimos had anything to do with his prayer for help.'),
    ('65e9155d-afb9-5c40-a9d5-9f18eff44f98', 'xoblutORPNA', 40, 286670, 292060, 'True, there are plenty of religious people who seem arrogantly certain of their own interpretations, too.'),
    ('6c7f15ea-f99c-5dad-bfed-cc299fd50bb0', 'xoblutORPNA', 41, 292670, 296980, 'They''re probably even more repulsive than atheists, at least to most of us.'),
    ('74cc11e1-ce96-5924-9aec-fb57e9140568', 'xoblutORPNA', 42, 297950, 303800, 'But religious dogmatists'' problem is exactly the same as the story''s unbeliever: blind certainty.'),
    ('6caaad0c-5d99-549e-b30c-6f3861a40ad6', 'xoblutORPNA', 43, 304530, 309780, 'A close-mindedness that amounts to an imprisonment so total that the prisoner doesn''t even know he''s locked up.'),
    ('1bee35f6-6eec-5aeb-bc91-5d0a40cb512e', 'xoblutORPNA', 44, 311550, 317860, 'The point here is that I think this is one part of what teaching me how to think is really supposed to mean.'),
    ('5ba35d9f-ba71-545c-9c3b-b5ed2a913c82', 'xoblutORPNA', 45, 318110, 319840, 'To be just a little less arrogant.'),
    ('5c09a9ad-89d7-56fa-88a9-4743c36c2071', 'xoblutORPNA', 46, 320450, 324519, 'To have just a little critical awareness about myself and my certainties.'),
    ('a9045ff6-b3ed-5006-833d-97bd8650f135', 'xoblutORPNA', 47, 324970, 332640, 'Because a huge percentage of the stuff that I tend to be automatically certain of is, it turns out, totally wrong and deluded.'),
    ('40a4ced6-3d5d-57f3-82d3-7d171f0e8b51', 'xoblutORPNA', 48, 333730, 338000, 'I have learned this the hard way, as I predict you graduates will, too.'),
    ('789e958f-a553-5f4e-a5b8-fa5796c30f5b', 'xoblutORPNA', 49, 338810, 343579, 'Here is just one example of the total wrongness of something I tend to be automatically sure of:'),
    ('bd5b3db6-1f5c-56d4-8b6b-eba648d64a61', 'xoblutORPNA', 50, 344210, 350599, 'everything in my own immediate experience supports my deep belief that I am the absolute center of the universe.'),
    ('fe2a6284-45cb-5277-9dcd-a55677863944', 'xoblutORPNA', 51, 351870, 355580, 'The realest, most vivid and important person in existence.'),
    ('b8c4fb44-e234-5400-aaa5-b373a96ce8ea', 'xoblutORPNA', 52, 356410, 361880, 'We rarely talk about this sort of natural, basic self-centeredness because it''s so socially repulsive.'),
    ('f557126c-edb2-5f9e-b264-4270d1d45b67', 'xoblutORPNA', 53, 362110, 364199, 'But it''s pretty much the same for all of us.'),
    ('ff47d6e1-5c75-5dfc-a2d9-bbd1cbf5eacd', 'xoblutORPNA', 54, 364750, 369120, 'It is our default setting, hard-wired into our boards at birth.'),
    ('7435b4b2-1c6a-57d4-b688-a6cf0d0b6f42', 'xoblutORPNA', 55, 376010, 382699, 'The world as you experience it is there in front of YOU or behind YOU, to the left or right of YOU,'),
    ('b08b6fe4-07fc-5ddb-9069-ffdc4e05c621', 'xoblutORPNA', 56, 382930, 385220, 'on YOUR TV or YOUR monitor.'),
    ('637b90a0-0868-55cc-9dad-d856fb0aa826', 'xoblutORPNA', 57, 385370, 386320, 'And so on.'),
    ('41989ea0-06db-53fb-b990-7f141bdb9d86', 'xoblutORPNA', 58, 386750, 394320, 'Other people''s thoughts and feelings have to be communicated to you somehow, but your own are so immediate, urgent, real.'),
    ('53607a7a-1f10-5cad-84a5-ac61718020ac', 'xoblutORPNA', 59, 395750, 401859, 'Please don''t worry that I''m getting ready to lecture you about compassion or other-directedness or all the so-called virtues.'),
    ('1f474cb5-bc4a-5c7b-953a-798586efde84', 'xoblutORPNA', 60, 402270, 403980, 'This is not a matter of virtue.'),
    ('33dcf8a6-de96-595b-b345-55ca915bd522', 'xoblutORPNA', 61, 404310, 409682, 'It''s a matter of my choosing to do the work of somehow altering or getting free of my natural,'),
    ('13168925-9ab0-5313-970b-d93d70f1373e', 'xoblutORPNA', 62, 409682, 418300, 'hard-wired default setting which is to be deeply and literally self-centered and to see and interpret everything through this lens of self.'),
    ('f385c8b3-2b69-5f88-b750-66ccef5a772a', 'xoblutORPNA', 63, 419570, 428159, 'People who can adjust their natural default setting this way are often described as being "well-adjusted", which I suggest to you is not an accidental term.'),
    ('cd18c04f-6806-5a67-af31-65d683565e5e', 'xoblutORPNA', 64, 429890, 438520, 'Given the triumphant academic setting here, an obvious question is how much of this work of adjusting our default setting involves actual knowledge or intellect.'),
    ('dd8ec3be-548f-50b5-abb5-632f9411c79b', 'xoblutORPNA', 65, 439050, 440660, 'This question gets very tricky.'),
    ('01b1ea1c-46db-5676-9517-95eae5db2491', 'xoblutORPNA', 66, 441650, 449780, 'Probably the most dangerous thing about an academic education - at least in my own case - is that it enables my tendency to over-intellectualize stuff,'),
    ('83f38d5d-7496-5eda-ab68-8be92bd3140c', 'xoblutORPNA', 67, 450370, 457020, 'to get lost in abstract arguments inside my head, instead of simply paying attention to what is going on right in front of me,'),
    ('91b9bd5f-70b3-52bd-bd20-b1a92502e26e', 'xoblutORPNA', 68, 457930, 460420, 'paying attention to what is going on inside me.'),
    ('814ef9b6-2479-5002-b85c-706cd767f348', 'xoblutORPNA', 69, 462190, 466950, 'As I''m sure you guys know by now, it is extremely difficult to stay alert and attentive,'),
    ('ba3b59d6-3d01-55bc-ad1d-8cc340ecb2a5', 'xoblutORPNA', 70, 466950, 472880, 'instead of getting hypnotized by the constant monologue inside your own head.'),
    ('a366b84d-3834-5ba2-9513-c9682963d0f6', 'xoblutORPNA', 71, 473930, 476080, 'Twenty years after my own graduation,'),
    ('c9f11505-3ab0-5ea8-8ece-a692d95da462', 'xoblutORPNA', 72, 476370, 483620, 'I have come gradually to understand that the liberal arts cliché about teaching you how to think is actually shorthand for a much deeper,'),
    ('d93c8328-7d0a-5cb4-89bc-108cb0019a61', 'xoblutORPNA', 73, 483870, 491439, 'more serious idea: learning how to think really means learning how to exercise some control over how and what you think.'),
    ('7b2b154d-be63-587d-8094-7a27543595c4', 'xoblutORPNA', 74, 492150, 499620, 'It means being conscious and aware enough to choose what you pay attention to and to choose how you construct meaning from experience.'),
    ('308b52d7-2526-552b-bd23-c08fb2d61f1f', 'xoblutORPNA', 75, 500630, 505979, 'Because if you cannot exercise this kind of choice in adult life, you will be totally hosed.'),
    ('87960740-b716-5913-9c25-977edd38a5e9', 'xoblutORPNA', 76, 507070, 512539, 'Think of the old cliché about, quote, the mind being an excellent servant but a terrible master.'),
    ('8d91bf96-b3e1-5494-a05e-e6f3b71c576c', 'xoblutORPNA', 77, 513610, 520640, 'This, like many clichés, so lame and unexciting on the surface, actually expresses a great and terrible truth.'),
    ('b4749ce2-65af-5006-9872-6ef30166b24b', 'xoblutORPNA', 78, 521690, 529080, 'It is not the least bit coincidental that adults who commit suicide with firearms almost always shoot themselves in: the head.'),
    ('fce15b16-ede0-5c96-864f-b04a559b499b', 'xoblutORPNA', 79, 529890, 532000, 'They shoot the terrible master.'),
    ('00ec1433-7848-5fac-b1e6-f09706b0035b', 'xoblutORPNA', 80, 532950, 537419, 'And the truth is that most of these suicides are actually dead long before they pull the trigger.'),
    ('9c56ed64-709a-5cfe-8826-afbdfa6093e9', 'xoblutORPNA', 81, 538810, 544620, 'And I submit that this is what the real, no bullshit value of your liberal arts education is supposed to be about:'),
    ('d39cb115-5c78-5cc1-ab43-2182aef311c7', 'xoblutORPNA', 82, 545150, 551000, 'how to keep from going through your comfortable, prosperous, respectable adult life dead.'),
    ('73ac05e2-7879-5b86-8884-6da76af5487b', 'xoblutORPNA', 83, 553050, 560060, 'A slave to your head and to your natural default setting of being uniquely, completely, imperially alone.'),
    ('2edb9cd3-9093-5b41-9b3f-e63f4d49993d', 'xoblutORPNA', 84, 560650, 561820, 'Day in and day out.'),
    ('18d76198-5e7b-55d5-b3f2-a52e6ad90fa3', 'xoblutORPNA', 85, 564670, 567760, 'That may sound like hyperbole, or abstract nonsense.'),
    ('c8092e5f-3890-5b7b-92ec-15af4f79a30b', 'xoblutORPNA', 86, 568770, 570160, 'Let''s get concrete.'),
    ('398cdd86-7354-5391-af23-0f6f004b023c', 'xoblutORPNA', 87, 570390, 576759, 'The plain fact is that you graduating seniors do not yet have any clue what "day in day out" really means.'),
    ('7ca6ebf8-859d-5fec-a28e-31b9be83a6da', 'xoblutORPNA', 88, 578530, 583720, 'There happen to be whole, large parts of adult American life that nobody talks about in commencement speeches.'),
    ('58e20cd4-2cf0-5226-a161-b5e6e8cabf00', 'xoblutORPNA', 89, 585530, 590120, 'One such part involves boredom, routine, and petty frustration.'),
    ('c498f7e6-a89c-5f4a-b968-d288d91e02a8', 'xoblutORPNA', 90, 590730, 594060, 'The parents and older folks here will know all too well what I''m talking about.'),
    ('c737406e-72fe-53aa-b029-181afc46b091', 'xoblutORPNA', 91, 595050, 602699, 'By way of example, let''s say it''s an average adult day, and you get up in the morning, go to your challenging, white-collar, college-graduate job,'),
    ('07d68442-2503-5a65-a915-e663352a6e6e', 'xoblutORPNA', 92, 602890, 604899, 'and you work hard for eight or ten hours,'),
    ('63c1bee0-f217-563a-8284-658267d3cd0a', 'xoblutORPNA', 93, 605010, 611271, 'and at the end of the day you''re tired and somewhat stressed and all you want is to go home and have a good supper and maybe unwind for an hour,'),
    ('52b08d19-82d9-5882-b0a7-353eb83fa583', 'xoblutORPNA', 94, 611271, 615440, 'and then hit the sack early because, of course, you have to get up the next day and do it all again.'),
    ('d1eaa5f8-5cd1-5ebd-9c00-42622bb3501e', 'xoblutORPNA', 95, 616070, 618219, 'But then you remember there''s no food at home.'),
    ('43c2ff3e-775f-57a8-bc91-d95347d8f228', 'xoblutORPNA', 96, 618650, 623863, 'You haven''t had time to shop this week because of your challenging job, and so now, after work,'),
    ('ee78cb7e-43c4-52db-9c75-e035ccca6bde', 'xoblutORPNA', 97, 623863, 626559, 'you have to get in your car and drive to the supermarket.'),
    ('94e84835-f40b-58ff-84e5-dae41554cd37', 'xoblutORPNA', 98, 627170, 631100, 'It''s the end of the work day and the traffic is apt to be very bad.'),
    ('d75534e6-3ffa-52aa-a213-e8fb7af77b84', 'xoblutORPNA', 99, 631470, 637639, 'So getting to the store takes way longer than it should, and when you finally get there, the supermarket is very crowded,'),
    ('fc17fa30-21ae-5fcd-b278-d3f5c85c161e', 'xoblutORPNA', 100, 637730, 642860, 'because of course it''s the time of day when all the other people with jobs also try to squeeze in some grocery shopping.'),
    ('fbfc8070-c5f0-5bb7-8d4f-122855db1c35', 'xoblutORPNA', 101, 643450, 653200, 'And the store is hideously, fluorescently, lit and infused with soul-killing muzak or corporate pop and it''s pretty much the last place you want to be,'),
    ('79f69fea-796e-571d-b62c-47d7b0351b11', 'xoblutORPNA', 102, 653200, 657524, 'but you can''t just get in and quickly out; you have to wander all over the huge,'),
    ('f586aeee-e8a8-5f1d-ad89-f5942792ba18', 'xoblutORPNA', 103, 657524, 664254, 'over-lit store''s confusing aisles to find the stuff you want and you have to maneuver your junky cart through all these other tired,'),
    ('c94bc490-02af-50a3-9bda-a0d35789b9f2', 'xoblutORPNA', 104, 664254, 670940, 'hurried people with carts and eventually...'),
    ('1719eb3c-f1d2-5078-9d37-28793f5bd09c', 'xoblutORPNA', 105, 672550, 678680, 'you get all your supper supplies, except now it turns out there aren''t enough checkout lanes open even though it''s the end-of-the-day rush.'),
    ('37075d6a-93de-5fac-9f67-6d6ac75f7a96', 'xoblutORPNA', 106, 679150, 683239, 'So the checkout line is incredibly long, which is stupid and infuriating.'),
    ('a65f4978-13c4-5652-b323-71062a5b6cd3', 'xoblutORPNA', 107, 684090, 687760, 'But you can''t take your frustration out on the frantic lady working the register,'),
    ('081f2876-c566-529a-a2a3-af26ed199abd', 'xoblutORPNA', 108, 688210, 695259, 'who is overworked at a job whose daily tedium and meaninglessness surpasses the imagination of any of us here at a prestigious college.'),
    ('b1b63064-a0f6-56fa-9504-7c4a3ba34d04', 'xoblutORPNA', 109, 696070, 700630, 'But anyway, you finally get to the checkout line''s front, and you pay for your food,'),
    ('db434024-52df-51c9-8e99-bd9b20e6e6ea', 'xoblutORPNA', 110, 700630, 705400, 'and you get told to "Have a nice day" in a voice that is the absolute voice of death.'),
    ('27e958b2-9be3-5079-9f7e-bb2e78744042', 'xoblutORPNA', 111, 706610, 708892, 'And then you have to take your creepy, flimsy,'),
    ('2cb88bfa-1a25-579a-bf61-03fee4269234', 'xoblutORPNA', 112, 708892, 716496, 'plastic bags of groceries in your cart with the one crazy wheel that pulls maddeningly to the left, all the way out through the crowded, bumpy,'),
    ('b57729b0-6c60-549e-b1e1-2c2751ba82e6', 'xoblutORPNA', 113, 716496, 724220, 'littery parking lot, and then you have to drive all the way home through slow, heavy, SUV-intensive, rush-hour traffic, et cetera, et cetera.'),
    ('bcb1cf97-1074-521a-a550-12b5d8feb32a', 'xoblutORPNA', 114, 725250, 727160, 'Everyone here has done this, of course.'),
    ('91fac695-5f88-58f3-8dbd-a89f35d3a495', 'xoblutORPNA', 115, 727530, 734339, 'But it hasn''t yet been part of you graduates'' actual life routine, day, after week, after month, after year.'),
    ('9ce85cb3-9eb4-5fbe-98a4-97fe08a07994', 'xoblutORPNA', 116, 734570, 735700, 'But it will be.'),
    ('e7a64888-52b9-5abf-a80b-bed70c4a44db', 'xoblutORPNA', 117, 737130, 741639, 'And many more dreary, annoying, seemingly meaningless routines besides.'),
    ('79124eec-c5cb-593b-85e4-87de66006519', 'xoblutORPNA', 118, 742470, 743920, 'But that is not the point.'),
    ('f9bb060e-f143-514d-aef6-b264dd3e6a94', 'xoblutORPNA', 119, 743950, 749940, 'The point is that petty, frustrating crap like this is exactly where the work of choosing is gonna come in.'),
    ('fc724b0a-735f-5114-be83-68eaa98faf49', 'xoblutORPNA', 120, 750670, 755599, 'Because the traffic jams and crowded aisles and long checkout lines give me time to think.'),
    ('0948f788-a772-5d74-9a24-8bc563838b4a', 'xoblutORPNA', 121, 756270, 760619, 'And if I don''t make a conscious decision about how to think and what to pay attention to,'),
    ('abe00055-a097-5912-b5a5-3a13ba0b98f0', 'xoblutORPNA', 122, 760890, 764240, 'I''m gonna be pissed and miserable every time I have to shop.'),
    ('6190aac0-1e96-5f42-b68d-21470d57b4b7', 'xoblutORPNA', 123, 764870, 770200, 'Because my natural default setting is the certainty that situations like this are really all about me.'),
    ('ba105c77-b77e-5f88-bdc7-af370f39f0ed', 'xoblutORPNA', 124, 770830, 777788, 'About MY hungriness and MY fatigue and MY desire to just get home, and it''s going to seem, for all the world,'),
    ('82ef6e17-189b-56e6-ab2c-c80e19c270f3', 'xoblutORPNA', 125, 777788, 780060, 'like everybody else is just in my way.'),
    ('d61c22db-088e-55d9-9e6a-ebef0c7c03ab', 'xoblutORPNA', 126, 780730, 782660, 'And who are all these people in my way?'),
    ('e514a801-95b5-5a56-aec1-c2c0e7ec22fa', 'xoblutORPNA', 127, 783070, 789480, 'And look at how repulsive most of them are, and how stupid and cow-like and dead-eyed and nonhuman they seem in the checkout line,'),
    ('d3b069d6-3428-5103-9ae9-63b57e3a2088', 'xoblutORPNA', 128, 790030, 794820, 'or at how annoying and rude it is that people are talking loudly on cell phones in the middle of the line.'),
    ('926affa8-103d-5591-b640-07425e6e32da', 'xoblutORPNA', 129, 795210, 798080, 'And look at how deeply, personally unfair this is.'),
    ('832d277c-0424-57e4-8773-3f250b21af81', 'xoblutORPNA', 130, 799870, 804539, 'Or, of course, if I''m in a more socially conscious liberal arts form of my default setting,'),
    ('7f84e876-b192-55ad-8587-3f0408a00a73', 'xoblutORPNA', 131, 815174, 823315, 'selfish, forty-gallon tanks of gas, and I can dwell on the fact that the patriotic or religious bumper-stickers always seem to be on the biggest,'),
    ('d6b056f9-5f27-54dc-827b-5a9d28e2627a', 'xoblutORPNA', 132, 823315, 827740, 'most disgustingly selfish vehicles, driven by the ugliest...'),
    ('f30da801-a369-57d6-a2e3-beef32e0d12d', 'xoblutORPNA', 133, 836390, 839703, 'biggest, most disgustingly selfish vehicles, driven by the ugliest,'),
    ('f75217c3-bf0b-5324-bbed-9d06ffcfb7e0', 'xoblutORPNA', 134, 839703, 846879, 'most inconsiderate and aggressive drivers and I can think about how our children''s children will despise us for wasting all the future''s fuel,'),
    ('f042ba0e-619c-5e2f-8ef3-3695b8173ae7', 'xoblutORPNA', 135, 846950, 855420, 'and probably screwing up the climate, and how spoiled and stupid and selfish and disgusting we all are, and how modern consumer society just sucks,'),
    ('1d622214-f605-5c15-b2d7-71a6e9d67cb3', 'xoblutORPNA', 136, 856110, 857240, 'and so on and so forth.'),
    ('f3f6510b-2762-5ec5-8ffd-10b52516968a', 'xoblutORPNA', 137, 858550, 862059, 'If I choose to think this way in the store and on the freeway, fine.'),
    ('e1ad927f-9202-584b-b70b-8cb11c2d286a', 'xoblutORPNA', 138, 864010, 865240, 'Lots of us do.'),
    ('2ef12992-c6fd-581f-b0bc-84d4c2e1015a', 'xoblutORPNA', 139, 865570, 870320, 'Except thinking this way tends to be so easy and automatic that it doesn''t have to be a choice.'),
    ('40d18880-1988-5407-93fb-b0ad43208112', 'xoblutORPNA', 140, 870850, 872559, 'It is my natural default setting.'),
    ('d95f194d-7dcb-50f2-81de-1b8a14e9c4e6', 'xoblutORPNA', 141, 873250, 881139, 'It''s the automatic way that I experience the boring, frustrating, crowded parts of adult life when I''m operating on the automatic,'),
    ('fe5f226f-dcef-56c9-82a3-454405bc6bbe', 'xoblutORPNA', 142, 881139, 888299, 'unconscious belief that I am the center of the world, and that my immediate needs and feelings are what should determine the world''s priorities.'),
    ('c6da7993-64f7-5221-9135-bc8f845fc84d', 'xoblutORPNA', 143, 889150, 893279, 'The thing is that, of course, there are totally different ways to think about these kinds of situations.'),
    ('2ad8fb9d-15ee-57de-a6e8-580ca6f2be1d', 'xoblutORPNA', 144, 894250, 898220, 'In this traffic, all these vehicles stuck and idling in my way,'),
    ('7d8a2f8a-9c52-56ff-966e-9a67e9d8d606', 'xoblutORPNA', 145, 898890, 903799, 'it''s not impossible that some of these people in SUVs have been in horrible auto accidents in the past,'),
    ('9f97c392-faca-54e9-ac75-9ee61a92751c', 'xoblutORPNA', 146, 904250, 909427, 'and now find driving so terrifying that their therapist has all but ordered them to get a huge,'),
    ('78a388b5-54f9-55ca-8cb6-8d74f710cf72', 'xoblutORPNA', 147, 909427, 912219, 'heavy SUV so they can feel safe enough to drive.'),
    ('ff75681f-d19c-566c-a733-cde7bb57f9af', 'xoblutORPNA', 148, 913110, 920050, 'Or that the Hummer that just cut me off is maybe being driven by a father whose little child is hurt or sick in the seat next to him,'),
    ('34ab2f0c-da5b-5bfe-a9c0-849050215900', 'xoblutORPNA', 149, 920050, 925400, 'and he''s trying to get this kid to the hospital, and he''s in a way bigger, more legitimate hurry than I am:'),
    ('4cf6faef-a27d-5399-bd56-ed7b8db0a903', 'xoblutORPNA', 150, 925630, 927920, 'it is actually I who am in HIS way.'),
    ('253cb2d3-f245-52b2-af67-e2001f8b352f', 'xoblutORPNA', 151, 929250, 936920, 'Or I can choose to force myself to consider the likelihood that everyone else in the supermarket''s checkout line is just as bored and frustrated as I am,'),
    ('945171e0-fe6e-5963-87ee-74acd13be9f4', 'xoblutORPNA', 152, 937710, 942440, 'and that some of these people probably have much harder, more tedious or painful lives than I do.'),
    ('47aa4ad8-a8ca-5ca3-89fe-cfd3d62ba0d2', 'xoblutORPNA', 153, 943830, 948940, 'Again, please don''t think that I''m giving you moral advice, or that I''m saying you are supposed to think this way,'),
    ('d14c7d42-2ff1-5c23-86fa-8195eda49f89', 'xoblutORPNA', 154, 949070, 951900, 'or that anyone expects you to just automatically do it.'),
    ('de9a1fcc-fbb2-595b-8949-b49b5eea5409', 'xoblutORPNA', 155, 952130, 953180, 'Because it''s hard.'),
    ('84dd2ce8-ea1b-5b8e-8313-9b141d3ded25', 'xoblutORPNA', 156, 953610, 955340, 'It takes will and effort.'),
    ('45aa53f6-76b4-5eda-8661-47966e85009f', 'xoblutORPNA', 157, 955570, 960760, 'And if you are like me, some days you won''t be able to do it, or you just flat out won''t want to.'),
    ('d877ddc0-a4ec-5653-806f-314312edd706', 'xoblutORPNA', 158, 961630, 968874, 'But most days, if you''re aware enough to give yourself a choice, you can choose to look differently at this fat, dead-eyed,'),
    ('0f4c1eef-0f5b-5674-bf32-b2a8570529b9', 'xoblutORPNA', 159, 968874, 972440, 'over-made-up lady who just screamed at her kid in the checkout line.'),
    ('f5da8b4e-3fa3-5236-a4d7-3642363a0251', 'xoblutORPNA', 160, 973110, 975020, 'Maybe she''s not usually like this.'),
    ('0bec62ff-2df1-5f95-aa2b-c49f2c43c93d', 'xoblutORPNA', 161, 975550, 979980, 'Maybe she''s been up three straight nights holding the hand of her husband who is dying of bone cancer.'),
    ('134958ff-f6de-57eb-81b2-634fac5df808', 'xoblutORPNA', 162, 980650, 988670, 'Or maybe this very lady is the low-wage clerk at the motor vehicles department, who just yesterday helped your spouse resolve a horrific, infuriating,'),
    ('e68f3c5b-fa8e-513a-87bb-0e7867400862', 'xoblutORPNA', 163, 988670, 992260, 'red-tape problem through some small act of bureaucratic kindness.'),
    ('ac4ef930-7be8-5480-ad43-5335e5e1d812', 'xoblutORPNA', 164, 993370, 996820, 'Of course, none of this is likely, but it''s also not impossible.'),
    ('98171684-ea7e-566d-b9f3-fed0fe33cad0', 'xoblutORPNA', 165, 997530, 999620, 'It just depends what you what to consider.'),
    ('4cf871e4-6967-52c1-905d-45373b9ce528', 'xoblutORPNA', 166, 1000570, 1008679, 'If you''re automatically sure that you know what reality is, and who and what is really important if you wanna operate on your default setting,'),
    ('5528cc8d-b4c9-58e7-aae5-bb1fa147c2ed', 'xoblutORPNA', 167, 1008970, 1014200, 'then you, like me, probably won''t consider possibilities that aren''t annoying and miserable.'),
    ('816e125b-9a4a-5b8f-b169-6b96df6ed417', 'xoblutORPNA', 168, 1015210, 1021980, 'But if you really learn how to think, how to pay attention, then you will know you have other options.'),
    ('72535998-b40c-599d-ba6b-75fed67f48bd', 'xoblutORPNA', 169, 1022410, 1032500, 'It will actually be within your power to experience a crowded, hot, slow, consumer-hell type situation as not only meaningful, but sacred,'),
    ('2a4e719b-1bcd-5669-92c0-a6c866fc0962', 'xoblutORPNA', 170, 1033110, 1041340, 'on fire with the same force that lit the stars: love, fellowship, the mystical oneness of all things, deep down.'),
    ('35d21458-9484-5357-9d31-c8c38becae3f', 'xoblutORPNA', 171, 1042650, 1045240, 'Not that that mystical stuff is necessarily true.'),
    ('70574fff-27f1-5fa9-998e-3bad2e990ec4', 'xoblutORPNA', 172, 1045430, 1050460, 'The only thing that''s capital-t True is that YOU get to decide how you''re gonna try to see it.'),
    ('6d85aa33-f3a2-52e0-b92a-91a625530d61', 'xoblutORPNA', 173, 1051410, 1057300, 'This, I submit, is the freedom of real education, of learning how to be well-adjusted.'),
    ('eacd701b-8277-5aa7-a2a8-87cfd0d2c623', 'xoblutORPNA', 174, 1057490, 1060779, 'You get to consciously decide what has meaning and what doesn''t.'),
    ('941489c8-d942-5302-89e1-1bd0bde5cae7', 'xoblutORPNA', 175, 1061850, 1063840, 'You get to decide what to worship.'),
    ('309740cf-006c-55c6-a730-b465f545f62b', 'xoblutORPNA', 176, 1065970, 1073699, 'Because here''s something else that''s weird but true: in the day to day trenches of adult life, there is actually no such thing as atheism.'),
    ('3a98c2c4-e6d5-523d-a053-c5d18ab74630', 'xoblutORPNA', 177, 1074390, 1076579, 'There is no such thing as not worshipping.'),
    ('059c6f3b-6b73-5f51-9c2b-8a56c783b1e1', 'xoblutORPNA', 178, 1079090, 1081459, 'The only choice we get is what to worship.'),
    ('97e71ef8-b0eb-587d-bd16-8cce4abe3cd1', 'xoblutORPNA', 179, 1090050, 1096460, 'be it Yahweh or the Wiccan Mother Goddess, or the Four Noble Truths, or some inviolable set of ethical principles,'),
    ('bd3973bf-9d55-56b0-b80c-09cfcbb2c40b', 'xoblutORPNA', 180, 1096830, 1099959, 'is that pretty much anything else you worship will eat you alive.'),
    ('b67ff644-6d71-5fbf-b2e8-082b1d34a8e1', 'xoblutORPNA', 181, 1101030, 1107320, 'If you worship money and things, if they are where you tap real meaning in life, then you will never have enough.'),
    ('8281ae20-b8ef-570d-b716-ff676f11ea6a', 'xoblutORPNA', 182, 1107950, 1109580, 'Never feel you have enough.'),
    ('340e7344-a800-56b7-bb7a-7338ffba9d7b', 'xoblutORPNA', 183, 1111470, 1115939, 'Worship your own body and beauty and sexual allure and you will always feel ugly.'),
    ('d2c4c9e9-53f3-50f1-b3ff-f80eff54b741', 'xoblutORPNA', 184, 1116470, 1121599, 'And when time and age start showing, you will die a million deaths before they finally plant you.'),
    ('ed0d90c7-6dbd-542b-bb5b-fa26e36f94cd', 'xoblutORPNA', 185, 1122890, 1125219, 'On one level, we all know this stuff already.'),
    ('31b12c38-dbe4-580e-8f5c-58d7327d7a9e', 'xoblutORPNA', 186, 1125510, 1133819, 'It''s been codified as myths, proverbs, clichés, epigrams, parables; the skeleton of every great story.'),
    ('dafe3dfc-d97a-538b-ac4a-5e675450ffae', 'xoblutORPNA', 187, 1134390, 1138380, 'The whole trick is keeping the truth up front in daily consciousness.'),
    ('29e3b1e2-a1f2-5142-9620-22993d3b3b09', 'xoblutORPNA', 188, 1139370, 1146780, 'Worship power, you will end up feeling weak and afraid, and you will need ever more power over others to numb you to your own fear.'),
    ('6d1dcd3e-0c42-5d1f-b40f-8b8cde230b82', 'xoblutORPNA', 189, 1147470, 1155760, 'Worship your intellect, being seen as smart, you will end up feeling stupid, a fraud, always on the verge of being found out.'),
    ('a1023ffb-9d47-580f-aae1-cd67aef05a53', 'xoblutORPNA', 190, 1157190, 1163159, 'But the insidious thing about these forms of worship is not that they''re evil or sinful, it''s that they are unconscious.'),
    ('2b798ad8-16ca-50ae-94e0-e3ba8b92d18b', 'xoblutORPNA', 191, 1163670, 1165080, 'They are default settings.'),
    ('93d55ba8-f248-5a44-a4e3-7eac80fe9ad3', 'xoblutORPNA', 192, 1165890, 1169780, 'They''re the kind of worship you just gradually slip into, day after day,'),
    ('39707dbf-b74a-56b1-8adb-08409979980d', 'xoblutORPNA', 193, 1170030, 1176140, 'getting more and more selective about what you see and how you measure value without ever being fully aware that that''s what you''re doing.'),
    ('d7ef4542-c913-5276-a585-24b0d2bc18e2', 'xoblutORPNA', 194, 1177250, 1182240, 'And the so-called ''real world'' will not discourage you from operating on your default settings,'),
    ('3dda9b38-de47-5073-8027-00df06b50250', 'xoblutORPNA', 195, 1182850, 1192760, 'because the so-called ''real world'' of men and money and power hums merrily along on the fuel of fear and anger and frustration and craving and the worship of self.'),
    ('44e536f5-5d1c-5d5a-8158-c307dee83662', 'xoblutORPNA', 196, 1193650, 1200539, 'Our own present culture has harnessed these forces in ways that have yielded extraordinary wealth and comfort and personal freedom.'),
    ('0ae2efb2-0ece-552b-9d59-ce3a4abdd359', 'xoblutORPNA', 197, 1201630, 1208020, 'The freedom all to be lords of our tiny skull-sized kingdoms, alone at the center of all creation.'),
    ('815b69d8-b871-5b43-bc60-887a2f2a5157', 'xoblutORPNA', 198, 1208970, 1211579, 'This kind of freedom has much to recommend it.'),
    ('60344c58-ee21-5e64-a2eb-0032f839c8a6', 'xoblutORPNA', 199, 1212310, 1214639, 'But of course there are all different kinds of freedom,'),
    ('22d074e9-a9b2-53ad-b821-20eef172670a', 'xoblutORPNA', 200, 1215030, 1222420, 'and the kind that is most precious you will not hear much talked about much in the great outside world of wanting and achieving and displaying.'),
    ('cb0426eb-9b2f-50cd-bfb7-bc3587b72548', 'xoblutORPNA', 201, 1223410, 1233499, 'The really important kind of freedom involves attention, and awareness, and discipline, and being able truly to care about other people and to sacrifice for them,'),
    ('4758ea41-4dcd-5ed0-8e45-14ee6e49a356', 'xoblutORPNA', 202, 1233870, 1238740, 'over and over, in myriad, petty little unsexy ways, every day.'),
    ('66f52f1b-eb91-5cab-be85-49601f897e1e', 'xoblutORPNA', 203, 1239290, 1240860, 'That is real freedom.'),
    ('d49ae9c6-2439-53a7-80fa-70e97b136c00', 'xoblutORPNA', 204, 1241230, 1245520, 'That is being educated, and understanding how to think.'),
    ('f3e42431-d8c4-5c2f-b308-5b720bee0647', 'xoblutORPNA', 205, 1246030, 1248079, 'The alternative is unconsciousness.'),
    ('4035b100-cc44-5ae8-8c41-a3220f2432d4', 'xoblutORPNA', 206, 1248430, 1249540, 'The default setting.'),
    ('9c1551d4-1023-5f6c-a5f3-dd8fd743e69c', 'xoblutORPNA', 207, 1249790, 1250780, 'The rat race.'),
    ('a5816400-5f59-5b6b-908c-3bcd088b0771', 'xoblutORPNA', 208, 1251310, 1256519, 'The constant gnawing sense of having had, and lost, some infinite thing.'),
    ('31e27878-4f8c-5f65-bf35-fa874ae3e4e1', 'xoblutORPNA', 209, 1258110, 1264580, 'I know that this stuff probably doesn''t sound fun and breezy or grandly inspirational the way a commencement speech is supposed to sound.'),
    ('a9d5ebdc-89dd-5198-bbe4-db9f7858574b', 'xoblutORPNA', 210, 1265390, 1271480, 'What it is, as far as I can see, is the capital-t Truth, with a whole lot of rhetorical niceties stripped away.'),
    ('70313b44-e047-5c3f-88f4-84cd2c6376d6', 'xoblutORPNA', 211, 1272210, 1275139, 'You are, of course, free to think of it whatever you wish.'),
    ('abdb440a-c0fb-5719-a40f-1dfbdab6be74', 'xoblutORPNA', 212, 1276170, 1280599, 'But please don''t just dismiss it as just some finger-wagging Dr. Laura sermon.'),
    ('1866c41d-7663-5837-8be1-9170bec914f9', 'xoblutORPNA', 213, 1281310, 1288140, 'None of this stuff is really about morality or religion or dogma or big fancy questions of life after death.'),
    ('f60fc5e6-9f67-58e8-9c05-fb6e6b52ec6b', 'xoblutORPNA', 214, 1288650, 1291440, 'The capital-t Truth is about life BEFORE death.'),
    ('6494532a-1718-5472-98f6-de3de2668984', 'xoblutORPNA', 215, 1292910, 1301439, 'It is about the real value of a real education, which has almost nothing to do with knowledge, and everything to do with simple awareness;'),
    ('55171628-7b1e-58f7-a580-4881e705816d', 'xoblutORPNA', 216, 1302330, 1310539, 'awareness of what is so real and essential, so hidden in plain sight all around us, all the time, that we have to keep reminding ourselves,'),
    ('4783a8a2-0e0a-5819-8a63-2fbfddb545b9', 'xoblutORPNA', 217, 1311250, 1313960, 'over and over: This is water.'),
    ('23860199-c51b-5a6f-a6c1-0ab08b3fa9a8', 'xoblutORPNA', 218, 1314670, 1315720, 'This is water.'),
    ('72451bb0-5f52-5b6b-b196-972287e05d7c', 'yaQZFhrW0fU', 1, 520, 4530, 'Thank you very much.'),
    ('b355242e-9773-5016-9678-b25e099326ac', 'yaQZFhrW0fU', 2, 38150, 47540, 'I remember I had a serious girlfriend, whom I later married—that''s important to remember,'),
    ('cdc2918c-7d2d-510a-a34a-559b48d6fe81', 'yaQZFhrW0fU', 3, 47540, 51730, 'by the way—and I remember I was getting commissioned in the Navy that day.'),
    ('83c10f2c-981b-5c36-ac4d-24ec0d719060', 'yaQZFhrW0fU', 4, 51730, 59640, 'But of all the things I remember, I don''t have a clue who the commencement speaker was, and I certainly don''t remember anything they said.'),
    ('7ed44c9e-4b12-5339-8ecf-0e5d3374f875', 'yaQZFhrW0fU', 5, 74300, 76889, '"What starts here changes the world."'),
    ('1a02dea8-de98-5598-a6e6-f916f7e7fe4e', 'yaQZFhrW0fU', 6, 93910, 96240, 'That''s a lot of folks.'),
    ('b6dc6a94-d88a-5c21-b66f-693ce6417f23', 'yaQZFhrW0fU', 7, 123760, 130070, 'Go one more generation and you can change the entire population of the world: eight billion people.'),
    ('8c7bc1bb-ef6a-5c40-a72d-24eda2f52610', 'yaQZFhrW0fU', 8, 135600, 138340, 'I saw it happen every day in Iraq and Afghanistan.'),
    ('49c26890-41d7-5708-9c3c-b6718b6deab6', 'yaQZFhrW0fU', 9, 138340, 145260, 'A young Army officer makes a decision to go left instead of right down a road in Baghdad,'),
    ('2530e9c7-8ad8-5d90-b83b-bc6c882ecd7e', 'yaQZFhrW0fU', 10, 148440, 151147, 'In Kandahar province in Afghanistan,'),
    ('9794db2c-1670-5b8b-95af-59429c8face1', 'yaQZFhrW0fU', 11, 161751, 163890, 'saving the lives of a dozen soldiers.'),
    ('4066863c-d01c-5467-9ba5-f3c9f6a0da9b', 'yaQZFhrW0fU', 12, 163890, 172580, 'But, if you think about it, not only were these soldiers saved by the decisions of one person, but their children were saved.'),
    ('f4ce917d-4423-5520-8e5e-66a13c4780fd', 'yaQZFhrW0fU', 13, 172580, 174880, 'And their children''s children.'),
    ('a0f147e8-dba7-54bc-84c5-316a3dd16179', 'yaQZFhrW0fU', 14, 174880, 179350, 'Generations were saved by one decision, by one person.'),
    ('3ca8bc62-85a0-5119-ae39-899526d950f9', 'yaQZFhrW0fU', 15, 179350, 183050, 'But changing the world can happen anywhere, and anyone can do it.'),
    ('379374e2-ebb0-5412-a33c-4c29dfca15c9', 'yaQZFhrW0fU', 16, 183050, 190100, 'So, what starts here can indeed change the world, but the question is: What will the world look like after you change it?'),
    ('69822871-90f3-5e04-becb-24694d74108c', 'yaQZFhrW0fU', 17, 190100, 194030, 'Well, I am confident that it will look much, much better.'),
    ('f6fb3796-a32d-5a65-a212-a1513243fada', 'yaQZFhrW0fU', 18, 194030, 196539, 'But if you will humor this old sailor for just a moment,'),
    ('996286fa-18af-5ce5-bf73-b4f4b084c61a', 'yaQZFhrW0fU', 19, 196539, 200250, 'I have a few suggestions that may help you on your way to a better a world.'),
    ('1b65f24a-abfd-5cfe-88d5-455ac6ebc92c', 'yaQZFhrW0fU', 20, 200250, 204325, 'And while these lessons were learned during my time in the military,'),
    ('096c4724-3c18-55e6-8f49-3d3bc4906d3b', 'yaQZFhrW0fU', 21, 204325, 208280, 'I can assure you that it matters not whether you ever served a day in uniform.'),
    ('6cf4f68f-7bd0-5244-9bb6-cff8b53b095c', 'yaQZFhrW0fU', 22, 208280, 214860, 'It matters not your gender, your ethnic or religious background, your orientation, or your social status.'),
    ('80b67e45-0867-5d4a-8a09-305e99751112', 'yaQZFhrW0fU', 23, 214860, 216827, 'Our struggles in this world are similar,'),
    ('aa02f560-93b1-5d33-aafb-164333332d3e', 'yaQZFhrW0fU', 24, 216827, 225910, 'and the lessons to overcome those struggles and to move forward—changing ourselves and changing the world around us—will apply equally to all.'),
    ('b79dfae8-5214-5285-b1f4-696073bf0995', 'yaQZFhrW0fU', 25, 228600, 233880, 'But it all began when I left UT for Basic SEAL training in Coronado, California.'),
    ('8b7f1cfb-0a7a-5e59-8f4b-96ebf01fd3a4', 'yaQZFhrW0fU', 26, 233880, 242201, 'Basic SEAL training is six months of long, torturous runs in the soft sand, midnight swims in the cold water off San Diego, obstacles courses,'),
    ('303be266-5502-5d1a-927d-b73477a15235', 'yaQZFhrW0fU', 27, 242201, 247200, 'unending calisthenics, days without sleep and always being cold, wet and miserable.'),
    ('651d35ef-d72c-5aa7-9681-38e3856dc4d7', 'yaQZFhrW0fU', 28, 247200, 262100, 'It is six months of being constantly harassed by professionally trained warriors who seek to find the weak of mind and body and eliminate them from ever becoming a Navy SEAL.'),
    ('61f23fb4-bc0d-55b6-8e1a-81d09a3b3e92', 'yaQZFhrW0fU', 29, 262100, 271730, 'But the training also seeks to find those students who can lead in an environment of constant stress, chaos, failure and hardships.'),
    ('8209b149-2c71-5df5-9870-0bf38f7e97bd', 'yaQZFhrW0fU', 30, 271730, 276320, 'To me, basic SEAL training was a lifetime of challenges crammed into six months.'),
    ('ce114bb9-1779-5b02-9e80-d2646917e026', 'yaQZFhrW0fU', 31, 284840, 292521, 'Every morning in SEAL training, my instructors, who at the time were all Viet Nam veterans, would show up in my barracks room,'),
    ('4a11d2e2-0a2c-5a36-ba68-9b8632d96973', 'yaQZFhrW0fU', 32, 292521, 295540, 'and the first thing they would inspect was my bed.'),
    ('4254237f-0dd6-5a6f-bf5c-984761b96fd3', 'yaQZFhrW0fU', 33, 295540, 299542, 'If you did it right, the corners would be square, the covers pulled tight,'),
    ('d5db90be-82a2-5e39-83ed-df079ec3ead5', 'yaQZFhrW0fU', 34, 299542, 305270, 'the pillow centered just under the headboard and the extra blanket folded neatly at the foot of the rack.'),
    ('d4bb1b5c-1a14-5323-9f14-3b65e0ad325d', 'yaQZFhrW0fU', 35, 305270, 308660, 'It was a simple task, mundane at best.'),
    ('707ac8ad-d30d-5d37-9c89-61ee5d86bd47', 'yaQZFhrW0fU', 36, 308660, 313170, 'But every morning we were required to make our bed to perfection.'),
    ('49a0d377-147a-5264-bcaf-93e8828b2618', 'yaQZFhrW0fU', 37, 313170, 322170, 'It seemed a little ridiculous at the time, particularly in light of the fact that were aspiring to be real warriors, tough battle-hardened SEALs.'),
    ('a91f3c9f-8930-58b0-af9c-5cedd373fc58', 'yaQZFhrW0fU', 38, 322170, 327380, 'But the wisdom of this simple act has been proven to me many times over.'),
    ('ecb10373-d61f-5766-91c6-ad7b55d037eb', 'yaQZFhrW0fU', 39, 327380, 332850, 'If you make your bed every morning you will have accomplished the first task of the day.'),
    ('7a972fab-9ef5-597d-9940-047cf83a779e', 'yaQZFhrW0fU', 40, 332850, 341260, 'It will give you a small sense of pride and it will encourage you to do another task, and another, and another.'),
    ('8c1fdfdd-1f8f-56c1-8ce5-dfcd9bbe9018', 'yaQZFhrW0fU', 41, 341260, 346180, 'And by the end of the day, that one task completed will have turned into many tasks completed.'),
    ('ca38b498-6583-57fa-9d3a-959e3b88d987', 'yaQZFhrW0fU', 42, 346180, 350570, 'Making your bed will also reinforce the fact that the little things in life matter.'),
    ('25160806-5d2d-58b4-bed0-049a171c5212', 'yaQZFhrW0fU', 43, 350570, 355630, 'If you can''t do the little things right, you will never be able to do the big things right.'),
    ('d4cd7da1-e29c-5add-95a8-a206ec0e5e92', 'yaQZFhrW0fU', 44, 355630, 358768, 'And, if by chance you have a miserable day,'),
    ('4fdc4365-48a8-52f7-b262-a91a2b8a408f', 'yaQZFhrW0fU', 45, 358768, 369190, 'you will come home to a bed that is made—that you made—and a made bed gives you encouragement that tomorrow will be better.'),
    ('54fdc92e-a8af-5e68-823b-8afdd236dae2', 'yaQZFhrW0fU', 46, 369190, 373810, 'If you want to change the world, start off by making your bed.'),
    ('37043b30-ec37-5f47-8b97-753e5f56f703', 'yaQZFhrW0fU', 47, 380850, 387870, 'Each crew is seven students—three on each side of a small rubber boat and one coxswain to help guide the dingy.'),
    ('ede25f7b-ced7-5f90-aa1c-7838e112c5b5', 'yaQZFhrW0fU', 48, 387870, 393890, 'Every day your boat crew forms up on the beach and is instructed to get through the surf zone and paddle several miles down the coast.'),
    ('c587b94e-1cb2-56db-8967-a09e3375264a', 'yaQZFhrW0fU', 49, 393890, 395005, 'In the winter,'),
    ('b4168f19-664d-58e3-9b00-cd2fc81c5342', 'yaQZFhrW0fU', 50, 405450, 410339, 'Every paddle must be synchronized to the stroke count of the coxswain.'),
    ('400d1e13-28b6-50dd-839e-b9d4d8e0d7d1', 'yaQZFhrW0fU', 51, 410339, 417589, 'Everyone must exert equal effort or the boat will turn against the wave and be unceremoniously dumped back on the beach.'),
    ('25529add-c2d5-54a1-a882-c026f7015bbe', 'yaQZFhrW0fU', 52, 417589, 422490, 'For the boat to make it to its destination, everyone must paddle.'),
    ('f20a41e6-4d31-5f30-ae30-5bfd87bca026', 'yaQZFhrW0fU', 53, 422490, 426350, 'You can''t change the world alone—you will need some help.'),
    ('88d7d18a-c2ff-5970-9a48-d04c5d25b939', 'yaQZFhrW0fU', 54, 426350, 435550, 'And to truly get from your starting point to your destination takes friends, colleagues, the good will of strangers and a strong coxswain to guide you.'),
    ('de0e9164-2db4-563c-90c9-25c5c4d6c8da', 'yaQZFhrW0fU', 55, 435550, 441009, 'If you want to change the world, find someone to help you paddle.'),
    ('e025c03c-090e-55fa-9145-930cc248435b', 'yaQZFhrW0fU', 56, 448360, 450610, 'There were now six boat crews of seven men each.'),
    ('8f8cebbb-c1c0-5e61-9680-c206e95b9605', 'yaQZFhrW0fU', 57, 450610, 460055, 'I was in the boat with the tall guys, but the best boat crew we had was made up of the little guys—"the munchkin crew,"'),
    ('a5ca28d2-99c5-563d-aa6c-0432496be33a', 'yaQZFhrW0fU', 58, 460055, 462869, 'we called them—no one was over five-foot-five.'),
    ('9641daf6-d39f-5241-a22b-10c47c377896', 'yaQZFhrW0fU', 59, 462869, 470858, 'The munchkin boat crew had one American Indian, one African American, one Polish America, one Greek American, one Italian American,'),
    ('4ae10d85-8199-57db-a2f3-6c77770c54d1', 'yaQZFhrW0fU', 60, 470858, 472910, 'and two tough kids from the Midwest.'),
    ('f95be691-d953-5d12-9b60-144211bf1f00', 'yaQZFhrW0fU', 61, 472910, 477839, 'They out-paddled, out-ran and out-swam all the other boat crews.'),
    ('8a338360-5a17-5d44-b3de-c009aff87944', 'yaQZFhrW0fU', 62, 477839, 489940, 'The big men in the other boat crews would always make good-natured fun of the tiny little flippers the munchkins put on their tiny little feet prior to every swim.'),
    ('07bc6e9a-9888-5336-8143-b22aa1f01308', 'yaQZFhrW0fU', 63, 489940, 495570, 'But somehow these little guys, from every corner of the nation and the world, always had the last laugh,'),
    ('3f773b39-b4fc-5238-a79e-e0eddec0b95a', 'yaQZFhrW0fU', 64, 495570, 501040, 'swimming faster than everyone and reaching the shore long before the rest of us.'),
    ('e6bafe7a-da6e-5a98-a85a-85866d6cccdc', 'yaQZFhrW0fU', 65, 501040, 503540, 'SEAL training was a great equalizer.'),
    ('f2a2ddf2-a002-5c37-b5d0-214b8a4701ac', 'yaQZFhrW0fU', 66, 503540, 506250, 'Nothing mattered but your will to succeed.'),
    ('a45e9083-af71-523c-a2ba-75b4832e6d05', 'yaQZFhrW0fU', 67, 506250, 510720, 'Not your color, not your ethnic background, not your education and not your social status.'),
    ('2c55faad-a636-5236-a4a9-41b666d9674b', 'yaQZFhrW0fU', 68, 510720, 518880, 'If you want to change the world, measure a person by the size of their heart, not by the size of their flippers.'),
    ('928391c8-ceb2-51ab-b5d1-086dcfd71973', 'yaQZFhrW0fU', 69, 518880, 524060, 'Several times a week, the instructors would line up the class and do a uniform inspection.'),
    ('46eabf38-631b-5490-87b4-032bf4e82ee1', 'yaQZFhrW0fU', 70, 524060, 526460, 'It was exceptionally thorough.'),
    ('c9541ba6-44c4-5fee-bca6-add164e27580', 'yaQZFhrW0fU', 71, 526460, 533180, 'Your hat had to be perfectly starched, your uniform immaculately pressed and your belt buckle shiny and void of any smudges.'),
    ('cbc90185-414a-510b-91f6-464a9625da19', 'yaQZFhrW0fU', 72, 533180, 540681, 'But it seemed that no matter how much effort you put into starching your hat, or pressing your uniform or polishing your belt buckle,'),
    ('548e3936-4253-563d-a5fc-92c82d6a831c', 'yaQZFhrW0fU', 73, 540681, 542470, 'it just wasn''t good enough.'),
    ('56d9b6c5-168f-5c88-a6c4-5ddba5c921e0', 'yaQZFhrW0fU', 74, 542470, 545330, 'The instructors would fine something wrong.'),
    ('406b865f-c88f-5b1f-b1f8-1355227027f5', 'yaQZFhrW0fU', 75, 545330, 551260, 'For failing the uniform inspection, the student had to run, fully clothed into the surf zone.'),
    ('73de8e9d-fc42-5650-8a78-2fac6c7e1eb9', 'yaQZFhrW0fU', 76, 551260, 557780, 'Then, wet from head to toe, roll around on the beach until every part of your body was covered with sand.'),
    ('6587333d-d0ab-5c5d-8af7-2e0da2f35251', 'yaQZFhrW0fU', 77, 557780, 562270, 'The effect was known as "sugar cookie."'),
    ('dba308f6-2882-56d4-a10b-b659572a0e55', 'yaQZFhrW0fU', 78, 562270, 566020, 'You stayed in the uniform the rest of the day—cold, wet and sandy.'),
    ('f0686fd9-6794-5469-9d33-172f5fc8a5a8', 'yaQZFhrW0fU', 79, 566020, 571870, 'There were many a student who just couldn''t accept the fact that all their efforts were in vain.'),
    ('635ba5f2-98cc-5800-a2de-316dd8f71e6c', 'yaQZFhrW0fU', 80, 571870, 576390, 'That no matter how hard they tried to get the uniform right, it was unappreciated.'),
    ('d885e6b5-2d64-5bbc-b03f-06607bd0154d', 'yaQZFhrW0fU', 81, 576390, 578840, 'Those students didn''t make it through training.'),
    ('778bc810-37c8-59ab-a795-ae31bc8669a5', 'yaQZFhrW0fU', 82, 578840, 582900, 'Those students didn''t understand the purpose of the drill.'),
    ('41c8bdb2-ca14-5c3f-ac4a-dc70e9425e15', 'yaQZFhrW0fU', 83, 582900, 584850, 'You were never going to succeed.'),
    ('2dfe8c92-c1b7-58c7-80ef-f45e37a2f31a', 'yaQZFhrW0fU', 84, 584850, 586720, 'You were never going to have a perfect uniform.'),
    ('b79f4514-99bc-5b2c-8b91-e1aa78a82ef5', 'yaQZFhrW0fU', 85, 586720, 589930, 'The instructors weren''t going to allow it.'),
    ('336a402a-b582-5fa4-93fa-5d5f0e0c9e46', 'yaQZFhrW0fU', 86, 589930, 596630, 'Sometimes no matter how well you prepare or how well you perform you still end up as a sugar cookie.'),
    ('70bb574c-360c-5db9-af2d-40aee3a4507f', 'yaQZFhrW0fU', 87, 596630, 599320, 'It''s just the way life is sometimes.'),
    ('002d0053-4b3e-5df5-a6ce-8d370e87eb59', 'yaQZFhrW0fU', 88, 599320, 605690, 'If you want to change the world, get over being a sugar cookie and keep moving forward.'),
    ('9680368a-bcff-5df0-b1b2-9467d0ccb402', 'yaQZFhrW0fU', 89, 605690, 615780, 'Every day during training you were challenged with multiple physical events—long runs, long swims, obstacle courses, hours of calisthenics—something designed to test your mettle.'),
    ('f4e28af2-9c47-5ccc-bd17-bc9a103927c8', 'yaQZFhrW0fU', 90, 615780, 618240, 'Every event had standards, times you had to meet.'),
    ('4d4b7a22-360c-5375-955a-56b161e31715', 'yaQZFhrW0fU', 91, 618240, 621376, 'If you failed to meet those times, those standards,'),
    ('3f5130dc-c49c-5562-94c8-d6082d54857b', 'yaQZFhrW0fU', 92, 621376, 629240, 'your name was posted on a list and at the end of the day those on the list were invited to a "circus."'),
    ('a3646388-fdbd-5ad4-9c9d-cbfead6fa7a6', 'yaQZFhrW0fU', 93, 629240, 635300, 'A circus was two hours of additional calisthenics, designed to wear you down, to break your spirit, to force you to quit.'),
    ('3cbf06da-52cf-58bb-af26-54072d4b3629', 'yaQZFhrW0fU', 94, 635300, 637740, 'No one wanted a circus.'),
    ('18f0c5e2-5799-5e50-bac1-42d69d6ab6e7', 'yaQZFhrW0fU', 95, 637740, 641160, 'A circus meant that for that day you didn''t measure up.'),
    ('056d22f3-6f98-55d3-845b-bf2a0001160e', 'yaQZFhrW0fU', 96, 641160, 647990, 'A circus meant more fatigue, and more fatigue meant that the following day would be more difficult, and more circuses were likely.'),
    ('bf53202d-49c6-5ffa-a2f3-3e9c773d5421', 'yaQZFhrW0fU', 97, 647990, 655470, 'But at some time during SEAL training, everyone—everyone—made the circus list.'),
    ('9738e1e5-d029-504e-81ac-f3de25fb5af4', 'yaQZFhrW0fU', 98, 655470, 659920, 'But an interesting thing happened to those who were constantly on the list.'),
    ('8c966bfc-ffa7-5b63-8e3c-2826b2fdbd04', 'yaQZFhrW0fU', 99, 659920, 668080, 'Over time, those students—who did two hours of extra calisthenics—got stronger and stronger.'),
    ('a2a912a0-20dc-59ae-9821-4ff828aa5c64', 'yaQZFhrW0fU', 100, 668080, 671690, 'The pain of the circuses built inner strength and physical resiliency.'),
    ('6d840204-c8b1-5315-8bb5-dce93374beeb', 'yaQZFhrW0fU', 101, 671690, 675360, 'Life is filled with circuses.'),
    ('301dadd6-88dc-5c96-9984-540f43ade5c2', 'yaQZFhrW0fU', 102, 675360, 676910, 'You will fail.'),
    ('304c9364-b5f0-57ea-809c-7926894cf523', 'yaQZFhrW0fU', 103, 676910, 678210, 'You will likely fail often.'),
    ('ff203baf-4573-523f-be72-3b170199e9d0', 'yaQZFhrW0fU', 104, 678210, 679970, 'It will be painful.'),
    ('697eee9e-5552-5281-be55-043fe9512ecd', 'yaQZFhrW0fU', 105, 679970, 681580, 'It will be discouraging.'),
    ('1f75f735-699e-5fe4-9608-afcee46c2191', 'yaQZFhrW0fU', 106, 681580, 685350, 'At times it will test you to your very core.'),
    ('958bd648-fb58-59eb-be92-7ff8918114ff', 'yaQZFhrW0fU', 107, 685350, 690300, 'But if you want to change the world, don''t be afraid of the circuses.'),
    ('b98a0f3f-b25a-5edc-be40-6ed32094998f', 'yaQZFhrW0fU', 108, 690300, 695589, 'At least twice a week, the trainees were required to run the obstacle course.'),
    ('0c3fb9bf-8d4f-51d6-bc5e-1fd119c82acc', 'yaQZFhrW0fU', 109, 702490, 705840, 'But the most challenging obstacle was the slide for life.'),
    ('a528e6f7-41f4-5bb8-bbe3-cf7843bfbb4b', 'yaQZFhrW0fU', 110, 714409, 722520, 'You had to climb the three tiered tower and, once at the top, you grabbed the rope, swung underneath the rope and pulled yourself,'),
    ('12c5547e-8b78-5cb0-a2cd-268d77c5d823', 'yaQZFhrW0fU', 111, 722520, 725609, 'hand over hand, until you got to the other end.'),
    ('31accb74-f174-5270-aa60-543ef4d02ff2', 'yaQZFhrW0fU', 112, 730420, 732570, 'The record seemed unbeatable.'),
    ('a9c1a2cd-a575-573a-b3d2-2b2bc9c7575c', 'yaQZFhrW0fU', 113, 732570, 738960, 'Until one day, a student decided to go down the slide for life head first.'),
    ('04d359e2-0dd0-5d2a-be84-8192266814e1', 'yaQZFhrW0fU', 114, 738960, 746090, 'Instead of swinging his body underneath the rope and inching his way down, he bravely mounted the TOP of the rope and thrust himself forward.'),
    ('dfef7a6e-b1a3-5229-b6be-c5d00ee38f0a', 'yaQZFhrW0fU', 115, 746090, 751030, 'It was a dangerous move—seemingly foolish and fraught with risk.'),
    ('e6c575a8-a67e-5f7e-a595-7c90024cb401', 'yaQZFhrW0fU', 116, 751030, 752990, 'Failure could mean injury and being dropped from the course.'),
    ('fa26971e-90f7-5465-99e3-75c297133a42', 'yaQZFhrW0fU', 117, 752990, 757660, 'Without hesitation the student slid down the rope perilously fast.'),
    ('ffccd5f4-fb58-58a9-8e2f-b2175d7f2159', 'yaQZFhrW0fU', 118, 757660, 761470, 'Instead of several minutes, it only took him half that time.'),
    ('360cf9df-7420-5c02-bd1b-9c014050cb3d', 'yaQZFhrW0fU', 119, 761470, 765940, 'And by the end of the course he had broken the record.'),
    ('9fc0ff28-88e1-5160-b932-cad057d14ca3', 'yaQZFhrW0fU', 120, 765940, 772479, 'If you want to change the world, sometimes you have to slide down the obstacles head first.'),
    ('46c78060-4f97-59f1-a23b-e2a1908028ca', 'yaQZFhrW0fU', 121, 772479, 779000, 'During the land warfare phase of training, the students are flown out to San Clemente Island, which lies off the coast of San Diego.'),
    ('f55dad37-cae3-532f-8484-e098931984c8', 'yaQZFhrW0fU', 122, 779000, 782539, 'The waters off San Clemente are a breeding ground for the great white sharks.'),
    ('3cb29e7d-7445-5403-b17b-fd2855170280', 'yaQZFhrW0fU', 123, 782539, 787159, 'To pass SEAL training there are a series of long swims that must be completed.'),
    ('c89db09d-5e43-5f4e-9561-7e675290638c', 'yaQZFhrW0fU', 124, 787159, 789060, 'One is the night swim.'),
    ('72d9d356-b150-58e0-b9c8-1952c7ef2895', 'yaQZFhrW0fU', 125, 789060, 798250, 'Before the swim the instructors joyfully brief the students on all the species of sharks that inhabit the waters off San Clemente.'),
    ('970c3d07-7a01-5e12-a9e0-816b40f72c64', 'yaQZFhrW0fU', 126, 798250, 806120, 'They assure you, however, that no student has ever been eaten by a shark—at least not that they can remember.'),
    ('7004ff8e-c4b3-5e21-be43-27783b6357dc', 'yaQZFhrW0fU', 127, 806120, 814340, 'But, you are also taught that if a shark begins to circle your position, stand your ground.'),
    ('9d17caf2-146e-599f-99df-e4f8587edd36', 'yaQZFhrW0fU', 128, 814340, 816250, 'Do not swim away.'),
    ('307409eb-6f6f-53fc-9dc8-308ea47a71f8', 'yaQZFhrW0fU', 129, 816250, 818570, 'Do not act afraid.'),
    ('a3acd0a3-e664-5e27-ac27-d423f2376bf8', 'yaQZFhrW0fU', 130, 818570, 826018, 'And if the shark, hungry for a midnight snack, darts towards you, then summons up all your strength and punch him in the snout,'),
    ('36181de2-0427-5d4e-81da-5790b651f113', 'yaQZFhrW0fU', 131, 826018, 828310, 'and he will turn and swim away.'),
    ('ce20eed5-c66f-5883-908c-e3ceade29b58', 'yaQZFhrW0fU', 132, 828310, 831950, 'There are a lot of sharks in the world.'),
    ('b1b77a2c-69c7-507c-b9d4-fb6347ddc9e7', 'yaQZFhrW0fU', 133, 831950, 836219, 'If you hope to complete the swim you will have to deal with them.'),
    ('f5e98146-a8a6-5ab1-8f88-77f36f620003', 'yaQZFhrW0fU', 134, 836219, 842719, 'So, if you want to change the world, don''t back down from the sharks.'),
    ('68e8a99a-9d05-547b-b515-3b84925354a6', 'yaQZFhrW0fU', 135, 842719, 847620, 'As Navy SEALs one of our jobs is to conduct underwater attacks against enemy shipping.'),
    ('b89c5dc6-83b8-5f36-bca6-9ce6487dadd6', 'yaQZFhrW0fU', 136, 847620, 851250, 'We practiced this technique extensively during training.'),
    ('321f303b-b538-51f4-a3da-1fba8ae78543', 'yaQZFhrW0fU', 137, 851250, 857668, 'The ship attack mission is where a pair of SEAL divers is dropped off outside an enemy harbor and then swims well over two miles,'),
    ('30628395-ef5a-5ae4-bace-3d44dca815b7', 'yaQZFhrW0fU', 138, 857668, 864190, 'under water, using nothing but a depth gauge and a compass to get to the target.'),
    ('f447c6d3-5849-541d-90b3-029c048c6d24', 'yaQZFhrW0fU', 139, 864190, 871370, 'During the entire swim, even well below the surface, there is some light that comes through.'),
    ('2ae5c26e-3872-5ff2-88d0-4cb2e7f4c838', 'yaQZFhrW0fU', 140, 871370, 876310, 'It is comforting to know that there is open water above you.'),
    ('576dece1-802b-5572-8881-2c6fdc22f37d', 'yaQZFhrW0fU', 141, 876310, 880890, 'But as you approach the ship, which is tied to a pier, the light begins to fade.'),
    ('e8f1f3cb-f7e4-5eec-bcdd-440b0d55824f', 'yaQZFhrW0fU', 142, 880890, 884100, 'The steel structure of the ship blocks the moonlight.'),
    ('695a6e57-b22a-5f7e-abb1-6eea9acdf5f2', 'yaQZFhrW0fU', 143, 884100, 887010, 'It blocks the surrounding street lamps.'),
    ('f586d75b-817b-5157-9e40-dcafa86e346e', 'yaQZFhrW0fU', 144, 887010, 890170, 'It blocks all ambient light.'),
    ('f9d98996-b3c1-5e89-9945-131e4de7dfa5', 'yaQZFhrW0fU', 145, 890170, 896630, 'To be successful in your mission, you have to swim under the ship and find the keel: the centerline and the deepest part of the ship.'),
    ('722f1233-49d4-5dc3-9e28-3971ef859509', 'yaQZFhrW0fU', 146, 896630, 898510, 'This is your objective.'),
    ('25a61f0d-5f64-59dc-b1ea-ffbca6449224', 'yaQZFhrW0fU', 147, 898510, 903564, 'But the keel is also the darkest part of the ship—where you cannot see your hand in front of your face,'),
    ('8f9eeaa0-3520-5b2d-b5cf-b47b8ca6c74d', 'yaQZFhrW0fU', 148, 903564, 911680, 'where the noise from the ship''s machinery is deafening and where it get to be easily disoriented and you can fail.'),
    ('1bbbd4d7-2b21-568f-ad30-433b60f02b8f', 'yaQZFhrW0fU', 149, 911680, 919960, 'Every SEAL knows that under the keel, at the darkest moment of the mission, is the time when you need to be calm,'),
    ('df17bfe7-cb68-5823-8331-6b774399f0ab', 'yaQZFhrW0fU', 150, 919960, 925779, 'when you must be calm, when you must be composed, when all your tactical skills,'),
    ('2264e008-add8-5ba6-85ed-44d36b5ffc05', 'yaQZFhrW0fU', 151, 925779, 931409, 'your physical power and all your inner strength must be brought to bear.'),
    ('ae96b3c0-f7a1-5940-81cb-b45e351643d3', 'yaQZFhrW0fU', 152, 931409, 938510, 'If you want to change the world, you must be your very best in the darkest moments.'),
    ('5c07599c-d2ca-5632-8ace-2f59f7ebfc18', 'yaQZFhrW0fU', 153, 938510, 941870, 'The ninth week of training is referred to as "Hell Week."'),
    ('5a3b9fe7-9ad8-55dc-9bcf-9d8e426918f5', 'yaQZFhrW0fU', 154, 941870, 949860, 'It is six days of no sleep, constant physical and mental harassment and one special day at the Mud Flats.'),
    ('970ef365-37e3-515a-9e52-8698f404b59b', 'yaQZFhrW0fU', 155, 949860, 955954, 'The Mud Flats are area between San Diego and Tijuana where the water runs off and creates the Tijuana slues,'),
    ('eb5e2469-d67a-574a-9355-9b357d8edd01', 'yaQZFhrW0fU', 156, 955954, 960350, 'a swampy patch of terrain where the mud will engulf you.'),
    ('c7ad874a-c3ee-5e9b-9170-7739bf4fe210', 'yaQZFhrW0fU', 157, 967184, 972600, 'the howling wind and the incessant pressure to quit from the instructors.'),
    ('f3ac07ef-e38d-5404-baed-12c6bc00f9d5', 'yaQZFhrW0fU', 158, 972600, 982539, 'As the sun began to set that Wednesday evening, my training class, having committed some "egregious infraction of the rules," was ordered into the mud.'),
    ('7ab1e209-7a6c-5297-92c2-2a48d9ad5a88', 'yaQZFhrW0fU', 159, 982539, 987700, 'The mud consumed each man ''til there was nothing visible but our heads.'),
    ('93ba2739-c477-518e-b747-894da5a81084', 'yaQZFhrW0fU', 160, 987700, 993252, 'The instructors told us we could leave the mud if only five men would quit—only five men,'),
    ('8f4c9add-1f16-50fe-9479-859d4ea7db16', 'yaQZFhrW0fU', 161, 993252, 997760, 'just five men and we could get out of the oppressive cold.'),
    ('187111e6-e207-5e96-a0c7-acda4952a75d', 'yaQZFhrW0fU', 162, 997760, 1001979, 'Looking around the mud flat it was apparent that some students were about to give up.'),
    ('92a66d89-223a-5998-8532-c3e822a024d9', 'yaQZFhrW0fU', 163, 1001979, 1008520, 'It was still over eight hours till the sun came up, eight more hours of bone chilling cold.'),
    ('549cd87e-938d-5bc8-a139-df168dd2c6a0', 'yaQZFhrW0fU', 164, 1008520, 1014820, 'The chattering teeth and shivering moans of the trainees were so loud it was hard to hear anything.'),
    ('853daae7-6fa3-5da9-a525-f740c5165cc6', 'yaQZFhrW0fU', 165, 1014820, 1019440, 'And then, one voice began to echo through the night.'),
    ('64b71893-3352-55d1-94f8-d80a9e00b7cc', 'yaQZFhrW0fU', 166, 1019440, 1022360, 'One voice raised in song.'),
    ('c8222d55-7ba3-5890-bdcd-71010d8ea6b4', 'yaQZFhrW0fU', 167, 1022360, 1027999, 'The song was terribly out of tune but sung with great enthusiasm.'),
    ('7e7d027a-070e-595d-9571-2d570533dc30', 'yaQZFhrW0fU', 168, 1027999, 1033690, 'One voice became two, and two became three, and before long everyone in the class was singing.'),
    ('8d325557-a119-5610-8378-c4dd24934b8a', 'yaQZFhrW0fU', 169, 1033690, 1039239, 'The instructors threatened us with more time in the mud if we kept up the singing, but the singing persisted.'),
    ('a1e99f1b-3d18-53de-ad7e-9abdff9a8979', 'yaQZFhrW0fU', 170, 1039239, 1046999, 'And somehow the mud seemed a little warmer, and the wind a little tamer and the dawn not so far away.'),
    ('7bdcfe72-1921-59b9-b1c9-d842759e0a9d', 'yaQZFhrW0fU', 171, 1046999, 1052939, 'If I have learned anything in my time traveling the world, it is the power of hope.'),
    ('4b6840f3-2d3f-5092-ba6c-d76b5cfc83b0', 'yaQZFhrW0fU', 172, 1052939, 1064569, 'The power of one person—Washington, Lincoln, King, Mandela and even a young girl from Pakistan, Malala—one person can change the world by giving people hope.'),
    ('cbb15e7d-1668-5be9-814c-ec8955a66bd8', 'yaQZFhrW0fU', 173, 1064569, 1070050, 'So, if you want to change the world, start singing when you''re up to your neck in mud.'),
    ('e0c65a09-8344-5b35-9dd8-b148083667ca', 'yaQZFhrW0fU', 174, 1070050, 1074680, 'Finally, in SEAL training there is a bell.'),
    ('9b64da87-a744-5bff-a6dc-105dfd1bd9b2', 'yaQZFhrW0fU', 175, 1074680, 1081150, 'A brass bell that hangs in the center of the compound for all the students to see.'),
    ('46458f82-0435-55d1-bae4-298ce1a75b04', 'yaQZFhrW0fU', 176, 1081150, 1084850, 'All you have to do to quit is ring the bell.'),
    ('880a26ea-4115-539f-bdaa-8868f1666dad', 'yaQZFhrW0fU', 177, 1087930, 1092820, 'Ring the bell and you no longer have to be in the freezing cold swims.'),
    ('3fc84d3e-da98-5ede-8262-7ccf5c74fc7a', 'yaQZFhrW0fU', 178, 1097351, 1102670, 'and you no longer have to endure the hardships of training.'),
    ('d4f3c850-0ae7-56fe-bc80-f623c97de3e8', 'yaQZFhrW0fU', 179, 1102670, 1106290, 'All you have to do is ring the bell to get out.'),
    ('02ed88c4-fa69-5ebc-9d30-4f108c953775', 'yaQZFhrW0fU', 180, 1106290, 1112379, 'If you want to change the world don''t ever, ever ring the bell.'),
    ('9029c349-9602-52db-b74c-a4c6e422aee5', 'yaQZFhrW0fU', 181, 1117239, 1120189, 'Moments away from beginning your journey through life.'),
    ('ce0e0bde-d1c9-5595-b1a8-31d6ea6ce25d', 'yaQZFhrW0fU', 182, 1120189, 1123829, 'Moments away from starting to change the world for the better.'),
    ('a3685a06-e8f8-5cf0-a19a-5cec25423829', 'yaQZFhrW0fU', 183, 1123829, 1125209, 'It will not be easy.'),
    ('61e880e7-b7a4-570a-969a-a98446fe2bc8', 'yaQZFhrW0fU', 184, 1131719, 1134310, 'Start each day with a task completed.'),
    ('4618915f-e994-5b59-a989-e45b34c2cffd', 'yaQZFhrW0fU', 185, 1134310, 1135978, 'Find someone to help you through life.'),
    ('4dfd879e-a830-5492-bacb-ed4fa57a2d49', 'yaQZFhrW0fU', 186, 1137030, 1144546, 'Know that life is not fair and that you will fail often, but if take you take some risks, step up when the times are toughest,'),
    ('1c6d5752-bebf-549e-be06-ff2d7858a4e0', 'yaQZFhrW0fU', 187, 1144546, 1150305, 'face down the bullies, lift up the downtrodden and never, ever give up—if you do these things,'),
    ('53fea2f2-7a4f-59c8-813b-4074bfb0643f', 'yaQZFhrW0fU', 188, 1150305, 1157091, 'the next generation and the generations that follow will live in a world far better than the one we have today,'),
    ('5efb4d4e-2357-54bd-a4d0-fa115fca5ca0', 'yaQZFhrW0fU', 189, 1157091, 1163229, 'and what started here will indeed have changed the world—for the better.'),
    ('f7c45d8d-75dd-5619-b28f-73a92ab75479', 'yaQZFhrW0fU', 190, 1163229, 1164520, 'Thank you very much.'),
    ('132ac685-cf2b-555e-a595-d4f451946871', 'yaQZFhrW0fU', 191, 1164520, 1166769, 'Hook ''em horns.'),
    ('4d1dc428-7617-5b4b-99d3-ec572648303e', 'yoEezZD71sc', 1, 27711, 31560, 'I presumed, to inspire their salespeople to greater heights.'),
    ('7a2498b6-9a1a-5e93-a322-9cd575a078ec', 'yoEezZD71sc', 2, 42719, 44669, 'It was weird.'),
    ('d059b259-76c7-59e5-aa23-c6e5e31c391d', 'yoEezZD71sc', 3, 44669, 55160, 'Software salespeople I think need to hear from someone who has had a long successful career in software sales not from an overly optimistic ex-mountaineer.'),
    ('3b6f5e1d-5050-5759-afb9-205d857b8a67', 'yoEezZD71sc', 4, 55160, 63522, 'Some poor guy who had arrived in the morning hoping to learn about sales techniques ended up going home worried about the blood flow to his extremities.'),
    ('113d90fc-ee8f-597a-95e0-70e82e2d4012', 'yoEezZD71sc', 5, 66123, 72279, 'And if the mountain was meant to be a symbol of life''s challenges and the loss of limbs a metaphor for sacrifice,'),
    ('93b8fa5e-ac61-50bb-bece-8803e94132fa', 'yoEezZD71sc', 6, 72279, 75110, 'the software guy is not going to get it, is he?'),
    ('3da157d2-89f9-596a-b05c-dfab90b9c11a', 'yoEezZD71sc', 7, 75110, 78378, 'Because he didn''t do an Arts degree, did he?'),
    ('7c452db3-ead0-5114-b935-e328f0432155', 'yoEezZD71sc', 8, 78378, 79540, 'He should have.'),
    ('4709ca36-e7ef-57a9-95fe-bd5957352fe6', 'yoEezZD71sc', 9, 94307, 98120, 'You won''t find it and it will bugger up your soufflé.'),
    ('7bbacc71-fcff-5b91-8b47-a13445410878', 'yoEezZD71sc', 10, 108035, 113782, 'I''ve never ever lost a limb on a mountainside metaphorically or otherwise and I''m certainly not going to give career advice because,'),
    ('22d69e56-d5fb-535a-a3e1-71747ddbdf4e', 'yoEezZD71sc', 11, 113782, 117480, 'well I''ve never really had what most would consider a job.'),
    ('66816003-724f-518e-96c9-4be2ce5baf5d', 'yoEezZD71sc', 12, 117480, 124990, 'However I have had large groups of people listening to what I say for quite a few years now and it''s given me an inflated sense of self importance.'),
    ('e907a255-b51a-53e0-a92f-6d6ced5d036c', 'yoEezZD71sc', 13, 128745, 139480, 'bestow upon you nine life lessons to echo of course the nine lessons of carols of the traditional Christmas service, which is also pretty obscure.'),
    ('48ffe73e-0196-5025-a66b-43ef1525e27d', 'yoEezZD71sc', 14, 141531, 145785, 'You will definitely find some of it boring and you will definitely forget all of it within a week.'),
    ('6e2d42c3-6776-5e6d-955e-402ac5c3f3fb', 'yoEezZD71sc', 15, 145785, 152876, 'And be warned there will be lots of similes and obscure aphorisms which start well but end up making no sense.'),
    ('5ffa687c-c968-5684-b885-39f6ddbd52c9', 'yoEezZD71sc', 16, 152876, 160659, 'So listen up or you''ll get lost like a blind man clapping in a pharmacy trying to echo-locate the contact lens fluid.'),
    ('729924ba-54a7-5c6f-a715-b28ef038aaef', 'yoEezZD71sc', 17, 160659, 167269, 'Looking for my old poetry teacher.'),
    ('61c1d431-25cd-550d-9256-6688b1c5dbd6', 'yoEezZD71sc', 18, 167269, 170949, 'Here we go, ready?'),
    ('0a95b26b-7843-5820-94eb-12c3d6e273b6', 'yoEezZD71sc', 19, 173077, 176650, 'Americans on talent shows always talk about their dreams.'),
    ('a6f63dd6-3224-54cc-824d-16890175817d', 'yoEezZD71sc', 20, 176650, 180860, 'Fine if you have something you''ve always wanted to do, dreamed of, like in your heart, go for it.'),
    ('b1b2f574-afbd-5992-9825-95bc6122b987', 'yoEezZD71sc', 21, 180860, 184041, 'After all it''s something to do with your time, chasing a dream.'),
    ('9a959c65-a933-5103-aec6-acaaa9fc1542', 'yoEezZD71sc', 22, 196409, 203099, 'I never really had one of these dreams and so I advocate passionate, dedication to the pursuit of short-term goals.'),
    ('42cbd66c-30c6-50b1-a993-6e9e3b0d63e7', 'yoEezZD71sc', 23, 203099, 204438, 'Be micro-ambitious.'),
    ('ad0825a8-9a91-5ab6-8aef-ab523d8c635e', 'yoEezZD71sc', 24, 204438, 208770, 'Put your head down and work with pride on whatever is in front of you.'),
    ('f052a26a-2db5-5568-ba20-1568808ee2d4', 'yoEezZD71sc', 25, 208770, 210815, 'You never know where you might end up.'),
    ('40cfe372-41d3-5e95-b975-431f5cffbc43', 'yoEezZD71sc', 26, 210815, 217655, 'Just be aware the next worthy pursuit will probably appear in your periphery, which is why you should be careful of long-term dreams.'),
    ('e66ee77d-5378-52ab-9197-a85da9dfcef4', 'yoEezZD71sc', 27, 217655, 223954, 'If you focus too far in front of you you won''t see the shiny thing out the corner of your eye.'),
    ('877a71e3-b736-5e81-9936-5aa2c6cb731c', 'yoEezZD71sc', 28, 224862, 227698, 'Advice metaphor - look at me go.'),
    ('5fbb9896-b1b8-569f-a475-f75000bcfb92', 'yoEezZD71sc', 29, 229603, 231616, 'Happiness is like an orgasm.'),
    ('de1191b4-2438-55ae-ba99-d4c58f837679', 'yoEezZD71sc', 30, 231616, 235231, 'If you think about it too much it goes away.'),
    ('ca94df36-ac87-5896-9ebc-ea596abe6dce', 'yoEezZD71sc', 31, 235231, 247166, 'Keep busy and aim to make someone else happy and you might find you get some as a side effect.'),
    ('058c2cad-e60b-5bae-920c-13ffb03c546f', 'yoEezZD71sc', 32, 247166, 249549, 'We didn''t evolve to be constantly content.'),
    ('8785c306-8fae-58a3-b116-116b99cd705b', 'yoEezZD71sc', 33, 249549, 253640, 'Contented Homo erectus got eaten before passing on their genes.'),
    ('00257120-9437-5e94-9389-32e6166baa22', 'yoEezZD71sc', 34, 255984, 258076, 'You are lucky to be here.'),
    ('347acab3-b75e-5959-b25b-e41281d612bd', 'yoEezZD71sc', 35, 258076, 266705, 'You are incalculably lucky to be born and incredibly lucky to be brought up by a nice family who encouraged you to go to uni.'),
    ('6803a687-e0a7-599f-beb3-377e97f6d11a', 'yoEezZD71sc', 36, 266705, 272489, 'Or if you were born into a horrible family that''s unlucky and you have my sympathy but you are still lucky.'),
    ('8e699a76-a230-5d36-86cb-ab7b024d4183', 'yoEezZD71sc', 37, 283063, 286129, 'Well done you for dragging yourself up by your shoelaces.'),
    ('6ad34c1a-04de-5962-a990-d29878ffb2b8', 'yoEezZD71sc', 38, 287025, 289794, 'You didn''t create the bit of you that dragged you up.'),
    ('31e59c80-614b-5b73-89af-9574c2b2004a', 'yoEezZD71sc', 39, 289794, 292139, 'They''re not even your shoelaces.'),
    ('f3d7dc98-5c77-537d-a3f6-4788d4a9c3cc', 'yoEezZD71sc', 40, 307151, 316025, 'Understanding that you can''t truly take credit for your successes nor truly blame others for their failures will humble you and make you more compassionate.'),
    ('3991cd5c-f10a-51f8-8317-2297851bf52e', 'yoEezZD71sc', 41, 316025, 317199, 'Empathy is intuitive.'),
    ('a9343dd7-1c2e-5bc0-af1a-d20ba6c14600', 'yoEezZD71sc', 42, 317199, 320989, 'It is also something you can work on intellectually.'),
    ('e1f39bbc-7366-5149-8ac1-f0cd42d59752', 'yoEezZD71sc', 43, 322083, 324183, 'I''m sorry you pasty, pale,'),
    ('13fbf0e2-e146-5540-9909-99e3813c3904', 'yoEezZD71sc', 44, 324183, 336100, 'smoking philosophy grads arching your eyebrows into a Cartesian curve as you watch the human movement mob winding their way through the miniature traffic cones of their existence.'),
    ('a147f27a-dca6-580d-8ec0-52898ae50484', 'yoEezZD71sc', 45, 336100, 337932, 'You are wrong and they are right.'),
    ('de2970f5-ca69-5380-bbe4-9440c971bfcd', 'yoEezZD71sc', 46, 337932, 339148, 'Well you''re half right.'),
    ('35f82665-fd47-5732-8b2d-8574f99b91a9', 'yoEezZD71sc', 47, 339148, 345147, 'You think therefore you are but also you jog therefore you sleep therefore you''re not overwhelmed by existential angst.'),
    ('ef398fd5-a739-57a4-be81-32e4e579617f', 'yoEezZD71sc', 48, 345147, 347600, 'You can''t be can''t and you don''t want to be.'),
    ('deba07ab-86ab-5e33-9eca-57c502e4e4b3', 'yoEezZD71sc', 49, 348408, 353588, 'Do yoga, pump iron, and run, whatever but take care of your body, you''re going to need it.'),
    ('ec77264e-e17a-5144-b78f-79c13bd1fb08', 'yoEezZD71sc', 50, 361354, 366589, 'And this long, luxurious life ahead of you is going to make you depressed.'),
    ('6685552f-4ac7-5797-926c-40fe467c1ae0', 'yoEezZD71sc', 51, 366589, 368127, 'But don''t despair.'),
    ('8e82e035-8eb0-5614-aebe-c30057fdd3e6', 'yoEezZD71sc', 52, 368127, 372649, 'There is correlation between depression and exercise.'),
    ('8215e57e-9fd7-5491-aa1f-e875d24b9097', 'yoEezZD71sc', 53, 373053, 376129, 'Run, my beautiful intellectuals run.'),
    ('1c6ae9d3-7072-5dc7-b952-81060c5ccc6a', 'yoEezZD71sc', 54, 385290, 394139, 'There is great wisdom in this but I would add that opinions differ significantly from assholes in that yours should be constantly and thoroughly examined.'),
    ('26be0b4c-c4aa-5df5-9883-0cbac53b1974', 'yoEezZD71sc', 55, 394139, 401289, 'I used to do exams in here - It''s revenge.'),
    ('427749da-906c-5953-9d96-c70e9f14b820', 'yoEezZD71sc', 56, 408139, 411735, 'We must think critically and not just about the ideas of others.'),
    ('09776935-e16f-50d4-979e-b544bab9d87c', 'yoEezZD71sc', 57, 411735, 413119, 'Be hard on your beliefs.'),
    ('1d55108e-a93a-597a-8186-e514d034e8f9', 'yoEezZD71sc', 58, 413119, 416299, 'Take them out onto the verandah and hit them with a cricket bat.'),
    ('51200d7d-f973-56e1-a201-ea6e39c9b45c', 'yoEezZD71sc', 59, 416299, 417669, 'Be intellectually rigorous.'),
    ('feda5080-23fc-54ec-9023-9c4a800ad952', 'yoEezZD71sc', 60, 417669, 421993, 'Identify your biases, your prejudices, your privileges.'),
    ('1cc2f61c-1eda-5d87-900a-adc2147a5cd5', 'yoEezZD71sc', 61, 421993, 426386, 'Most of society is kept alive by a failure to acknowledge nuance.'),
    ('80194a3c-c8bf-58af-a7bf-c986b6968be3', 'yoEezZD71sc', 62, 426386, 433796, 'We tend to generate false dichotomies and then try to argue one point using two entirely different sets of assumptions.'),
    ('460e3037-c182-5f53-9270-d42524d9e629', 'yoEezZD71sc', 63, 433796, 441979, 'Like two tennis players trying to win a match by hitting beautifully executed shots from either end of separate tennis courts.'),
    ('9e86f2fb-f090-5c92-a397-547d62447f1b', 'yoEezZD71sc', 64, 442299, 449226, 'while I have science and arts graduates in front of me please don''t make the mistake of thinking the arts and sciences are at odds with one another.'),
    ('6a48e17b-20f1-58e5-8df8-70802197b5b2', 'yoEezZD71sc', 65, 449226, 451799, 'That is a recent, stupid and damaging idea.'),
    ('e72431f6-4853-53c9-92af-005c5555b9e5', 'yoEezZD71sc', 66, 451799, 457172, 'You don''t have to be unscientific to make beautiful art, to write beautiful things.'),
    ('27823e3e-a3ef-5eec-9e06-6ce7bb640a7b', 'yoEezZD71sc', 67, 457172, 463878, 'If you need proof - Twain, Douglas Adams, Vonnegut, McEwan, Sagan and Shakespeare, Dickens for a start.'),
    ('4314f0eb-d0c4-53fe-a3f0-8c0c5291f95f', 'yoEezZD71sc', 68, 463878, 466698, 'You don''t need to be superstitious to be a poet.'),
    ('8eff4b55-f20a-503e-9db8-be725d82ddd2', 'yoEezZD71sc', 69, 466698, 470435, 'You don''t need to hate GM technology to care about the beauty of the planet.'),
    ('d1998517-d922-5881-b6a2-79cfb4d48675', 'yoEezZD71sc', 70, 470435, 473436, 'You don''t have to claim a soul to promote compassion.'),
    ('1883d29e-08d4-5e21-9504-055fe88736af', 'yoEezZD71sc', 71, 473436, 482476, 'Science is not a body of knowledge nor a belief system it''s just a term which describes human kinds'' incremental acquisition of understanding through observation.'),
    ('efba6004-dcfc-5bbe-8c5a-bc62f0681194', 'yoEezZD71sc', 72, 482476, 483635, 'Science is awesome!'),
    ('79f4a09b-fea9-5618-ba68-5969fa0eb918', 'yoEezZD71sc', 73, 483635, 488556, 'The arts and sciences need to work together to improve how knowledge is communicated.'),
    ('8b0da966-fe66-5624-9a26-20f1beb08eda', 'yoEezZD71sc', 74, 506056, 512269, '(audience laughs) The fact that that bristling is more to do with politics than science is even more despairing.'),
    ('9e85c829-50e2-5e6b-8d67-d8238aa9c956', 'yoEezZD71sc', 75, 514903, 516573, 'Please be a teacher.'),
    ('91290b64-0306-5ac0-b806-b740d61ce89a', 'yoEezZD71sc', 76, 516573, 521323, 'Teachers are the most admirable and important people in the world.'),
    ('2cd220e5-e7f2-574e-aae3-b67f7b7f37fe', 'yoEezZD71sc', 77, 521323, 526210, 'You don''t have to do it forever but if you''re in doubt about what to do be an amazing teacher.'),
    ('c0cce767-24e6-5110-8705-01a2b52bff43', 'yoEezZD71sc', 78, 528060, 529826, 'Be a primary school teacher.'),
    ('cfb36c09-bba4-5a04-a0fc-d0ca4ef96e5b', 'yoEezZD71sc', 79, 529826, 531549, 'Especially if you''re a bloke.'),
    ('73a3de6e-daad-5ddb-83ac-ed7285b2988f', 'yoEezZD71sc', 80, 531549, 533730, 'We need male primary school teachers.'),
    ('08b2d911-f808-5d29-ac74-84d083cef799', 'yoEezZD71sc', 81, 533730, 536617, 'Even if you''re not a teacher, be a teacher.'),
    ('ac61344a-4402-5414-bfc0-82fec64ac91a', 'yoEezZD71sc', 82, 536617, 537830, 'Share your ideas.'),
    ('c30ea179-701f-5d59-9156-0d352bec562e', 'yoEezZD71sc', 83, 537830, 540460, 'Don''t take for granted your education.'),
    ('ca40f94d-7e1e-58ef-837e-e81eaef2b23e', 'yoEezZD71sc', 84, 540460, 544320, 'Rejoice in what you learn and spray it.'),
    ('bcf8db0b-339f-58ee-a7f3-3c0fd20eea35', 'yoEezZD71sc', 85, 547175, 553185, 'I found myself doing this thing a bit recently where if someone asks me what sort of music I like I say.'),
    ('2bfe7d52-7a18-547f-a4c1-309b7ccbc2bd', 'yoEezZD71sc', 86, 553185, 558159, 'Well I don''t listen to the radio because pop song lyrics annoy me, or if someone asks me what food I like I say,'),
    ('59be1226-c5b3-5c18-95e6-776379723c92', 'yoEezZD71sc', 87, 558159, 561406, 'I think truffle oil is overused and slightly obnoxious.'),
    ('8c3620d2-a19f-5535-9542-7cba125eb143', 'yoEezZD71sc', 88, 561406, 570710, 'And I see it all the time online - people whose idea of being part of a subculture is to hate Coldplay or football or feminists or the Liberal Party.'),
    ('36a7cd27-a28c-5930-bcfe-6156307bcd39', 'yoEezZD71sc', 89, 570710, 574001, 'We have a tendency to define ourselves in opposition to stuff.'),
    ('a3a6bd22-cef4-5ca0-ada8-436c9b6ac4de', 'yoEezZD71sc', 90, 574001, 576372, 'As a comedian I make my living out of it.'),
    ('589aafb0-4480-5db0-9361-a714936058a0', 'yoEezZD71sc', 91, 576372, 579889, 'But try to also express your passion for things you love.'),
    ('a2063fac-41cb-5a49-b52c-2bdfc792d74a', 'yoEezZD71sc', 92, 579889, 583405, 'Be demonstrative and generous in your praise of those you admire.'),
    ('f5c7ce03-0bab-5a87-81f0-a4123d2a25f6', 'yoEezZD71sc', 93, 583405, 585890, 'Send thank you cards and give standing ovations.'),
    ('bafa3877-f42a-5346-9823-8e6a7d3ca02c', 'yoEezZD71sc', 94, 585890, 589800, 'Be pro stuff not just anti stuff.'),
    ('64c75565-ae38-5910-813f-819c34bfe890', 'yoEezZD71sc', 95, 603530, 609628, 'I don''t care if you''re the most powerful cat in the room, I will judge you on how you treat the least powerful.'),
    ('c29882ed-82fe-5159-8d5c-701b26e1c7e0', 'yoEezZD71sc', 96, 613240, 618510, 'You don''t need to know what you''re going to do with the rest of your life.'),
    ('e69a0e4c-6b28-5e97-a955-68b0e9ea5855', 'yoEezZD71sc', 97, 618510, 623859, 'I''m not saying sit around smoking cones all day but also don''t panic!'),
    ('dd44c3ce-32b5-5385-bec2-6d5f3f680fe9', 'yoEezZD71sc', 98, 630250, 634986, 'I said at the beginning of this ramble, which is already three-and-a-half minutes long, life is meaningless.'),
    ('676ea982-6d12-51e8-97ce-1eed3631dc4c', 'yoEezZD71sc', 99, 634986, 636940, 'It was not a flippant assertion.'),
    ('7c262f23-a4e1-533e-b85f-aaf3d3e05e15', 'yoEezZD71sc', 100, 645986, 650229, 'Leave it to humans to think the universe has a purpose for them.'),
    ('aae20923-cc31-52f4-902f-836f4c7a203f', 'yoEezZD71sc', 101, 650229, 651981, 'However I''m no nihilist.'),
    ('d8849c91-a8b5-57f7-944f-d279f5604f53', 'yoEezZD71sc', 102, 651981, 653524, 'I''m not even a cynic.'),
    ('f8c57d11-7930-576e-8a67-f7d6e02d01ee', 'yoEezZD71sc', 103, 653524, 659858, 'I am actually rather romantic and here''s my idea of romance: you will soon be dead.'),
    ('e1fb98fc-ffd8-5520-8ab2-02348c06fa7d', 'yoEezZD71sc', 104, 659858, 665725, 'Life will sometimes seem long and tough and God it''s tiring.'),
    ('f341b418-247c-5abd-9618-24384b2bd718', 'yoEezZD71sc', 105, 665725, 671938, 'And you will sometimes be happy and sometimes sad and then you''ll be old and then you''ll be dead.'),
    ('04ceb236-caac-5ded-b465-79c35fb186b7', 'yoEezZD71sc', 106, 671938, 678319, 'There is only one sensible thing to do with this empty existence and that is fill it.'),
    ('877985f7-7366-52fa-a26c-8808b5969b5e', 'yoEezZD71sc', 107, 679898, 689202, 'And in my opinion, until I change it, life is best filled by learning as much as you can about as much as you can.'),
    ('b6fc6d83-e4a3-5842-abed-99700a22afbb', 'yoEezZD71sc', 108, 689202, 691704, 'Taking pride in whatever you''re doing.'),
    ('ac6c0831-6df4-50f5-8f30-dcb76f3105a1', 'yoEezZD71sc', 109, 691704, 701813, 'Having compassion, sharing ideas, running, being enthusiastic and then there''s love and travel and wine and sex and art and kids and giving and mountain climbing,'),
    ('44de88df-de2d-52eb-a7ca-b97807aff7db', 'yoEezZD71sc', 110, 701813, 704600, 'but you know all that stuff already.'),
    ('d280e7f0-1822-596f-b820-d76b0bf95b3f', 'yoEezZD71sc', 111, 704600, 710578, 'It''s an incredibly exciting thing this one meaningless life of yours.'),
    ('0b3ac689-edd1-5133-a00d-a32e9b4b6989', 'yoEezZD71sc', 112, 710578, 714988, 'Good luck and thank you for indulging me.')
) AS x(id, youtube_id, n, start_ms, end_ms, transcript)
JOIN learning_videos v ON v.youtube_video_id = x.youtube_id
ON CONFLICT (id) DO NOTHING;

-- 2. move the old numbers out of the way, then number every sentence of these videos by time
UPDATE video_segments
SET sequence_no = sequence_no + 2000000
WHERE sequence_no < 1000000
  AND video_id IN (SELECT id FROM learning_videos WHERE youtube_video_id IN ('2QsxCYPZ-6o', '86x-u-tz0MA', 'CxC161GvMPc', 'E91bGT9BjYk', 'Frq4TZf0F1s', 'I_tRSrPru94', 'OyK0oE5rwFY', 'QBddNulwhKo', 'S7HCEtsEeJA', 'S7mfygW40Cs', 'SHXPpsIJTb0', 'V2EMuoM5IX4', 'dbnch1goJr8', 'eIho2S0ZahI', 'fLJsdqxnZb0', 'gedoSfZvBgE', 'gkjW9PZBRfk', 'hGt8njnS1R8', 'iCvmsMzlF7o', 'ibjUpk9Iagk', 'p7HKvqRI_Bo', 'pOLmD_WVY-E', 'rb7TVW77ZCs', 'reKgQh0E9kg', 'ri2uKTpw4lQ', 'rrkrvAUbU9Y', 'xQ156y4TtJs', 'xoblutORPNA', 'yaQZFhrW0fU', 'yoEezZD71sc'));

UPDATE video_segments s
SET sequence_no = r.rn
FROM (SELECT id, row_number() OVER (PARTITION BY video_id ORDER BY start_ms, end_ms, id) AS rn
      FROM video_segments
      WHERE video_id IN (SELECT id FROM learning_videos WHERE youtube_video_id IN ('2QsxCYPZ-6o', '86x-u-tz0MA', 'CxC161GvMPc', 'E91bGT9BjYk', 'Frq4TZf0F1s', 'I_tRSrPru94', 'OyK0oE5rwFY', 'QBddNulwhKo', 'S7HCEtsEeJA', 'S7mfygW40Cs', 'SHXPpsIJTb0', 'V2EMuoM5IX4', 'dbnch1goJr8', 'eIho2S0ZahI', 'fLJsdqxnZb0', 'gedoSfZvBgE', 'gkjW9PZBRfk', 'hGt8njnS1R8', 'iCvmsMzlF7o', 'ibjUpk9Iagk', 'p7HKvqRI_Bo', 'pOLmD_WVY-E', 'rb7TVW77ZCs', 'reKgQh0E9kg', 'ri2uKTpw4lQ', 'rrkrvAUbU9Y', 'xQ156y4TtJs', 'xoblutORPNA', 'yaQZFhrW0fU', 'yoEezZD71sc'))) r
WHERE s.id = r.id;
